VRT_L("tle-c-maths-r01",{"duree":15,"titre":"La division euclidienne dans ℕ","accroche":"Un quotient, un reste, et un calendrier devient prévisible.","intro":"La division euclidienne est la base de toute l'arithmétique de Terminale.","objectifs":["écrire une division euclidienne","justifier son unicité","résoudre un problème de reste"],"parties":[{"t":"Le théorème","html":"<div class='def'><b>Théorème</b>Pour tout entier naturel a et tout entier naturel non nul b, il existe un unique couple (q ; r) tel que <strong>a = bq + r</strong> et <strong>0 ≤ r < b</strong>.</div>"},{"t":"Exemple","html":"<p>1 000 = 7 × 142 + 6 : le reste de 1 000 par 7 est 6.</p>","labo":{"type":"pgcd","a":252,"b":105,"mode":"euclide"}},{"t":"Application","html":"<p>Si aujourd'hui est lundi, dans 1 000 jours, on aura avancé de 142 semaines et 6 jours : ce sera dimanche.</p>","retenir":"Le reste est strictement inférieur au diviseur."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> La division euclidienne de 47 par 5 donne :</p><ol type='a'><li>47 = 5 × 8 + 7</li><li>47 = 5 × 10 − 3</li><li>47 = 5 × 9,4</li><li>47 = 5 × 9 + 2</li></ol><details><summary>Voir la réponse</summary><p><strong>47 = 5 × 9 + 2</strong>. Le reste doit vérifier 0 ≤ r &amp;lt; 5.</p></details><p><strong>Exercice.</strong></p><p>Donne le reste de 2 026 par 9.</p><details><summary>Voir la réponse</summary><p>(Réponse : 1.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Pour l'excursion d'un lycée de Bertoua, 1 000 élèves doivent voyager dans des cars de 45 places. Le départ a lieu un lundi et le retour 2 026 jours plus tard pour un autre groupe.</p><p><strong>Tâche 1.</strong> Effectue la division euclidienne de 1 000 par 45 et déduis-en le nombre de cars.</p><p><strong>Tâche 2.</strong> Quel jour de la semaine tombe le 2 026e jour après un lundi ?</p><details><summary>Voir une réponse attendue</summary><p>1 000 = 45 × 22 + 10 : il faut 23 cars, le dernier transportant 10 élèves. 2 026 = 7 × 289 + 3 : on avance de 3 jours, c'est un jeudi.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["a = bq + r.","0 ≤ r < b.","Unicité de q et r."],"exo":"<p>Donne le reste de 2 026 par 9. <em>(Réponse : 1.)</em></p>","quiz":[{"q":"La division euclidienne de 47 par 5 donne :","r":["47 = 5 × 8 + 7","47 = 5 × 10 − 3","47 = 5 × 9,4","47 = 5 × 9 + 2"],"b":3,"e":"Le reste doit vérifier 0 ≤ r &lt; 5."},{"q":"Dans a = bq + r, le reste r vérifie :","r":["0 ≤ r &lt; b","0 &lt; r ≤ b","r ≥ b","r &lt; 0"],"b":0,"e":"C'est la condition qui rend la division unique."},{"q":"Le quotient de 100 par 7 est :","r":["15","14","2","7"],"b":1,"e":"7 × 14 = 98 et 100 − 98 = 2 &lt; 7."},{"q":"Le reste de 100 par 7 est :","r":["14","0","2","6"],"b":2,"e":"100 = 7 × 14 + 2."},{"q":"Un entier n est pair si le reste de sa division par 2 est :","r":["1","2","n","0"],"b":3,"e":"n est pair quand il s'écrit n = 2q, avec un reste nul."},{"q":"Les restes possibles dans la division par 4 sont :","r":["0, 1, 2 et 3","1, 2, 3 et 4","0 et 1","0, 2 et 4"],"b":0,"e":"Le reste est strictement inférieur à 4."},{"q":"Un entier impair s'écrit :","r":["2k","2k + 1","4k","k + 2"],"b":1,"e":"Le reste de sa division par 2 vaut 1."},{"q":"Le reste de 2026 dans la division par 9 est :","r":["0","4","1","8"],"b":2,"e":"9 × 225 = 2 025, donc 2 026 = 9 × 225 + 1."},{"q":"Si a = 7q + 3, le reste de 2a par 7 est :","r":["3","0","1","6"],"b":3,"e":"2a = 7(2q) + 6 avec 6 &lt; 7."},{"q":"La division euclidienne de a par b existe et est unique si :","r":["b est un entier non nul","b = 0","a &lt; b toujours","a et b sont premiers"],"b":0,"e":"C'est le théorème de la division euclidienne."}],"c":"Tle C","m":"maths","rang":1,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un berger de Mora doit répartir 1 000 têtes de bétail en enclos de 7, sans mélanger le reste.","tache":"Indique le nombre d'enclos complets et le nombre de bêtes restantes."},"gratuit":true});
VRT_L("tle-c-maths-r03",{"duree":25,"titre":"Divisibilité dans ℤ et congruences","accroche":"Calculer le reste de 2¹⁰⁰ sans calculer 2¹⁰⁰.","intro":"Les congruences permettent de raisonner sur les restes sans manipuler de très grands nombres.","objectifs":["définir la divisibilité","utiliser les congruences","calculer un reste"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>a <strong>divise</strong> b s'il existe k entier tel que b = ka. a est <strong>congru</strong> à b modulo n, noté <strong>a ≡ b [n]</strong>, si n divise a − b.</div>"},{"t":"Propriétés","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":3,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une radio communautaire de Garoua diffuse une publicité tous les 7 jours, et on cherche quel jour tombe sa 100ᵉ diffusion.","tache":"Explique comment les congruences aident à ce type de calcul."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r04",{"duree":20,"titre":"Les nombres premiers","accroche":"Les briques avec lesquelles tous les entiers sont construits.","intro":"Tout entier se décompose en produit de nombres premiers, de manière unique.","objectifs":["reconnaître un nombre premier","décomposer un entier","utiliser la décomposition"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>nombre premier</strong> est un entier naturel qui a exactement deux diviseurs : 1 et lui-même.</div><p>Il existe une infinité de nombres premiers.</p>"},{"t":"Test de primalité","verrou":true},{"t":"Décomposition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":4,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un club informatique de Yaoundé apprend que des codes secrets utilisent de très grands nombres premiers.","tache":"Indique comment tester si 97 est premier."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r05",{"duree":20,"titre":"PGCD et PPCM dans ℤ","accroche":"Des tuiles carrées, les plus grandes possible.","intro":"Le PGCD et le PPCM se calculent grâce à l'algorithme d'Euclide ou à la décomposition en facteurs premiers.","objectifs":["calculer un PGCD","utiliser les nombres premiers","résoudre un problème"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Le <strong>PGCD</strong> est le plus grand diviseur commun ; le <strong>PPCM</strong>, le plus petit multiple commun positif. On a <strong>PGCD(a ; b) × PPCM(a ; b) = |ab|</strong>.</div>"},{"t":"Avec la décomposition","verrou":true},{"t":"Premiers entre eux","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":5,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un carreleur de Bafoussam couvre un sol de 360 cm sur 84 cm avec des carreaux carrés entiers, les plus grands possible.","tache":"Détermine le côté du carreau."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r06",{"duree":30,"titre":"Bézout, Gauss et équations diophantiennes","accroche":"Trouver toutes les solutions entières d'une équation.","intro":"Une équation à coefficients entiers, résolue en nombres entiers, a des solutions très structurées.","objectifs":["énoncer Bézout et Gauss","trouver une solution particulière","décrire toutes les solutions"],"parties":[{"t":"Bézout","html":"<div class='def'><b>Théorème de Bézout</b>a et b sont premiers entre eux si et seulement s'il existe des entiers u et v tels que <strong>au + bv = 1</strong>.</div>"},{"t":"Gauss","verrou":true},{"t":"L'équation ax + by = c","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":6,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un jeu de la kermesse d'un lycée de Douala, on donne ou on reprend des jetons de 7 points et de 3 points pour arriver à un total exact.","tache":"Trouve toutes les façons d'obtenir un total de 1 point, les jetons repris étant comptés négativement."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r16",{"duree":25,"titre":"Espaces vectoriels sur ℝ","accroche":"Une même structure pour des vecteurs, des polynômes, des fonctions.","intro":"La notion d'espace vectoriel unifie de nombreux objets mathématiques.","objectifs":["reconnaître un espace vectoriel","identifier un sous-espace","trouver une base"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>espace vectoriel</strong> sur ℝ est un ensemble muni d'une addition et d'une multiplication par un réel vérifiant les règles usuelles du calcul vectoriel.</div>"},{"t":"Sous-espaces","verrou":true},{"t":"Base et dimension","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":16,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un logiciel de dessin créé par un club de Douala, chaque couleur est écrite par trois composantes (rouge, vert, bleu).","tache":"Propose une base de ces couleurs."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r17",{"duree":25,"titre":"Bijection réciproque et accroissements finis : applications","accroche":"Passer de la théorie à l'encadrement chiffré.","intro":"Cette séance revient sur les résultats de dérivabilité par des applications type bac.","objectifs":["calculer une dérivée réciproque","majorer une différence","prouver une convergence"],"parties":[{"t":"Application à la réciproque","html":"<div class='def'><b>Rappel</b><strong>(f⁻¹)'(y) = 1 / f'(f⁻¹(y))</strong>, si f' ne s'annule pas.</div><div class='ex'><b>Exemple</b>f(x) = x³ + x, f(1) = 2 : (f⁻¹)'(2) = 1 / f'(1) = 1/4.</div>"},{"t":"Majorer une différence","verrou":true},{"t":"Suites contractantes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":17,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un capteur de Kribi corrige à chaque mesure l'erreur précédente selon une loi dont le coefficient est inférieur à 1.","tache":"Dis ce que cela garantit pour l'erreur."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r18",{"duree":25,"titre":"Les applications linéaires","accroche":"Une transformation qui respecte l'addition et la multiplication.","intro":"Une application linéaire se résume à l'image d'une base et se traduit par une matrice.","objectifs":["reconnaître une application linéaire","écrire une matrice","déterminer noyau et image"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>f est <strong>linéaire</strong> si, pour tous vecteurs u, v et tout réel λ : <strong>f(u + v) = f(u) + f(v)</strong> et <strong>f(λu) = λf(u)</strong>.</div>"},{"t":"Matrice","verrou":true},{"t":"Noyau et image","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":18,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un jeu vidéo développé à Yaoundé projette chaque point (x ; y ; z) sur le sol (x ; y ; 0).","tache":"Détermine le noyau de cette projection."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r21",{"duree":20,"titre":"Orientation de l'espace et produit vectoriel","accroche":"La règle de la main droite, en mathématiques.","intro":"Le produit vectoriel fabrique un vecteur perpendiculaire à deux vecteurs donnés.","objectifs":["orienter l'espace","définir le produit vectoriel","appliquer la règle de la main droite"],"parties":[{"t":"Orientation","html":"<div class='def'><b>Définition</b>Une base (i ; j ; k) est <strong>directe</strong> si elle respecte la règle de la main droite : pouce, index, majeur.</div>"},{"t":"Le produit vectoriel","html":"<p>u ∧ v est le vecteur orthogonal à u et v, tel que (u ; v ; u ∧ v) soit directe, et de norme :</p><p class='formule'>‖u ∧ v‖ = ‖u‖ ‖v‖ |sin θ|</p>","labo":{"type":"vecteur"}},{"t":"Cas particulier","html":"<p>u ∧ v = 0 si et seulement si u et v sont colinéaires.</p>","retenir":"Le résultat du produit vectoriel est un vecteur."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Le produit vectoriel u ∧ v est :</p><ol type='a'><li>un nombre réel égal au produit des normes</li><li>un vecteur orthogonal à u et à v</li><li>un vecteur colinéaire à u</li><li>toujours le vecteur nul, quels que soient u et v</li></ol><details><summary>Voir la réponse</summary><p><strong>un vecteur orthogonal à u et à v</strong>. C'est sa propriété géométrique principale.</p></details><p><strong>Exercice.</strong></p><p>‖u‖ = 2, ‖v‖ = 3, θ = 90°. Calcule ‖u ∧ v‖.</p><details><summary>Voir la réponse</summary><p>(Réponse : 6.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un mécanicien applique une force F(0 ; 0 ; −50) (en N) au bout d'une clé, au point repéré par r(0,3 ; 0 ; 0) (en m) depuis l'axe du boulon. On considère aussi u(1 ; 2 ; −1) et v(2 ; 0 ; 3).</p><p><strong>Tâche 1.</strong> Calcule u ∧ v et vérifie qu'il est orthogonal à u.</p><p><strong>Tâche 2.</strong> Calcule le moment r ∧ F.</p><details><summary>Voir une réponse attendue</summary><p>u ∧ v = (2 × 3 − (−1) × 0 ; (−1) × 2 − 1 × 3 ; 1 × 0 − 2 × 2) = (6 ; −5 ; −4) ; u · (u ∧ v) = 6 − 10 + 4 = 0. r ∧ F = (0 ; 0,3 × 50 ; 0) = (0 ; 15 ; 0) N·m.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Base directe.","u ∧ v orthogonal à u et à v.","‖u ∧ v‖ = ‖u‖‖v‖ |sin θ|."],"exo":"<p>‖u‖ = 2, ‖v‖ = 3, θ = 90°. Calcule ‖u ∧ v‖. <em>(Réponse : 6.)</em></p>","quiz":[{"q":"Le produit vectoriel u ∧ v est :","r":["un nombre réel égal au produit des normes","un vecteur orthogonal à u et à v","un vecteur colinéaire à u","toujours le vecteur nul, quels que soient u et v"],"b":1,"e":"C'est sa propriété géométrique principale."},{"q":"La norme de u ∧ v vaut :","r":["‖u‖ ‖v‖ cos θ","‖u‖ + ‖v‖","‖u‖ ‖v‖ |sin θ|","u · v"],"b":2,"e":"θ est l'angle entre u et v."},{"q":"Le trièdre (u ; v ; u ∧ v) est :","r":["indirect","plat","nul toujours","direct"],"b":3,"e":"C'est la convention de l'orientation."},{"q":"La règle des trois doigts de la main droite sert à :","r":["déterminer le sens de u ∧ v","calculer un produit scalaire","trouver une norme","mesurer un angle"],"b":0,"e":"Pouce, index et majeur donnent un trièdre direct."},{"q":"i ∧ j dans une base orthonormée directe vaut :","r":["−k","k","0","i"],"b":1,"e":"(i ; j ; k) est directe."},{"q":"j ∧ i vaut :","r":["k","0","−k","j"],"b":2,"e":"Le produit vectoriel est antisymétrique."},{"q":"u ∧ u vaut :","r":["le vecteur u lui-même","le réel ‖u‖²","le vecteur unitaire de u","le vecteur nul"],"b":3,"e":"L'angle de u avec lui-même est nul et sin 0 = 0 : u ∧ u est nul."},{"q":"Si u ∧ v = 0 avec u et v non nuls, alors :","r":["u et v sont colinéaires","u et v sont orthogonaux","u = v","‖u‖ = ‖v‖"],"b":0,"e":"‖u‖ ‖v‖ |sin θ| = 0 impose sin θ = 0 : les vecteurs sont colinéaires."},{"q":"Une base orthonormée (i ; j ; k) est directe si :","r":["k = j ∧ i","k = i ∧ j","i = j","k = 0"],"b":1,"e":"C'est la définition de l'orientation directe."},{"q":"L'orientation de l'espace permet de définir :","r":["la longueur d'un vecteur et sa norme","le produit scalaire de deux vecteurs","le sens du produit vectoriel et des rotations","les coordonnées d'un point dans un repère quelconque"],"b":2,"e":"Sans orientation, u ∧ v serait défini au signe près."}],"c":"Tle C","m":"maths","rang":21,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un mécanicien de Douala serre un boulon : la force appliquée à l'extrémité de la clé produit une rotation.","tache":"Indique dans quelle direction est orienté le moment de la force."},"gratuit":true});
VRT_L("tle-c-maths-r22",{"duree":20,"titre":"Propriétés du produit vectoriel","accroche":"Un calcul simple à partir des coordonnées.","intro":"Dans une base orthonormée directe, le produit vectoriel se calcule directement.","objectifs":["utiliser l'antisymétrie","calculer avec des coordonnées","vérifier un résultat"],"parties":[{"t":"Propriétés","html":"<div class='def'><b>Propriétés</b><strong>v ∧ u = −(u ∧ v)</strong> ; le produit vectoriel est bilinéaire.</div>"},{"t":"Coordonnées","verrou":true},{"t":"Vérifier","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":22,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour calculer l'orientation d'un panneau solaire à Maroua, un élève utilise deux vecteurs portés par ce panneau.","tache":"Calcule le vecteur normal avec u(1 ; 2 ; 0) et v(0 ; 1 ; 3)."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r23",{"duree":25,"titre":"Applications du produit vectoriel","accroche":"Aires, plans et moments s'expriment simplement.","intro":"Le produit vectoriel sert à calculer des aires, à trouver des vecteurs normaux et à étudier des forces.","objectifs":["calculer une aire","écrire une équation de plan","calculer un moment"],"parties":[{"t":"Aires","html":"<div class='def'><b>Formules</b>L'aire du <strong>parallélogramme</strong> vaut ‖AB ∧ AC‖. L'aire du <strong>triangle ABC</strong> vaut <strong>(1/2)‖AB ∧ AC‖</strong>.</div>"},{"t":"Plan","verrou":true},{"t":"Moment d'une force","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":23,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un charpentier de Foumban doit estimer la surface d'une face triangulaire du toit, connaissant les coordonnées de trois points.","tache":"Dis quel calcul effectuer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r27",{"duree":20,"titre":"Limite d'une suite par comparaison","accroche":"Coincée entre deux suites, la suite n'a plus le choix.","intro":"Pour trouver une limite difficile, on encadre la suite par des suites plus simples.","objectifs":["appliquer le théorème des gendarmes","comparer à l'infini","rédiger une preuve"],"parties":[{"t":"Théorème des gendarmes","html":"<div class='def'><b>Théorème</b>Si vₙ ≤ uₙ ≤ wₙ et si (vₙ) et (wₙ) convergent vers L, alors <strong>(uₙ) converge vers L</strong>.</div>"},{"t":"Comparaison","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":27,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Les mesures d'une expérience de physique au lycée de Bafang sont toujours comprises entre deux valeurs qui se rapprochent de 5.","tache":"Conclus sur la limite des mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r47",{"duree":20,"titre":"Les fonctions x ↦ aˣ","accroche":"Une croissance à taux constant s'écrit avec aˣ.","intro":"Les fonctions exponentielles de base a généralisent la fonction eˣ.","objectifs":["définir aˣ","dériver aˣ","étudier le sens de variation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Pour a > 0, on définit <strong>aˣ = e^(x ln a)</strong>.</div>"},{"t":"Propriétés","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":47,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une mutuelle de Bafoussam annonce un taux annuel de 10 % sur un placement de 100 000 F.","tache":"Exprime le capital après x années."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r48",{"duree":15,"titre":"Les coniques : présentation générale","accroche":"Couper un cône de trois façons différentes.","intro":"Les trajectoires des planètes et la forme des antennes paraboliques sont des coniques.","objectifs":["identifier les trois coniques","relier coupe et courbe","citer des applications"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>coniques</strong> sont les courbes obtenues par l'intersection d'un cône de révolution et d'un plan : <strong>ellipse</strong>, <strong>parabole</strong>, <strong>hyperbole</strong>.</div>"},{"t":"Reconnaître","html":"<ul><li>Ellipse : courbe fermée.</li><li>Parabole : une seule branche ouverte.</li><li>Hyperbole : deux branches.</li></ul>","labo":{"type":"conique"}},{"t":"Applications","html":"<p>Les antennes paraboliques concentrent le signal au foyer. Les planètes décrivent des ellipses.</p>","retenir":"Le foyer est un point essentiel des coniques."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Les coniques sont les courbes obtenues par :</p><ol type='a'><li>la rotation d'une droite autour d'un axe</li><li>l'intersection de deux sphères</li><li>l'intersection d'un cône et d'un plan</li><li>le tracé d'un carré et de ses diagonales</li></ol><details><summary>Voir la réponse</summary><p><strong>l'intersection d'un cône et d'un plan</strong>. Ellipse, parabole et hyperbole en sont les trois types.</p></details><p><strong>Exercice.</strong></p><p>Quelle conique décrit une planète autour du Soleil ?</p><details><summary>Voir la réponse</summary><p>(Réponse : une ellipse.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Le contour d'un miroir est la courbe d'équation 9x² + 25y² = 225.</p><p><strong>Tâche 1.</strong> Mets l'équation sous forme réduite et identifie la conique.</p><p><strong>Tâche 2.</strong> Donne a, b, c, l'excentricité et les foyers.</p><details><summary>Voir une réponse attendue</summary><p>x²/25 + y²/9 = 1 : ellipse. a = 5, b = 3, c = √(25 − 9) = 4, e = 4/5 = 0,8, foyers F(4 ; 0) et F'(−4 ; 0).</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Ellipse, parabole, hyperbole.","Section d'un cône.","Foyer."],"exo":"<p>Quelle conique décrit une planète autour du Soleil ? <em>(Réponse : une ellipse.)</em></p>","quiz":[{"q":"Les coniques sont les courbes obtenues par :","r":["la rotation d'une droite autour d'un axe","l'intersection de deux sphères","l'intersection d'un cône et d'un plan","le tracé d'un carré et de ses diagonales"],"b":2,"e":"Ellipse, parabole et hyperbole en sont les trois types."},{"q":"Les trois types de coniques non dégénérées sont :","r":["le cercle, le carré et le triangle","la droite, le point et le plan","la sphère, le cône et le cylindre","l'ellipse, la parabole et l'hyperbole"],"b":3,"e":"Le cercle est un cas particulier d'ellipse."},{"q":"L'excentricité e d'une ellipse vérifie :","r":["0 ≤ e &lt; 1","e = 1","e > 1","e &lt; 0"],"b":0,"e":"Le cercle correspond à e = 0."},{"q":"L'excentricité d'une parabole est :","r":["e = 0","e = 1","e > 1","e &lt; 1"],"b":1,"e":"C'est la frontière entre ellipse et hyperbole."},{"q":"L'excentricité d'une hyperbole vérifie :","r":["e = 1","e &lt; 1","e > 1","e = 0"],"b":2,"e":"L'hyperbole a deux branches."},{"q":"Les orbites des planètes autour du Soleil sont :","r":["des paraboles","des hyperboles","des droites","des ellipses"],"b":3,"e":"C'est la première loi de Kepler."},{"q":"Une antenne parabolique utilise la propriété :","r":["les rayons parallèles à l'axe se concentrent au foyer","les rayons parallèles à l'axe divergent après réflexion","aucune propriété optique particulière","les rayons issus du foyer se concentrent au sommet"],"b":0,"e":"C'est la propriété optique de la parabole."},{"q":"L'équation x²/9 + y²/4 = 1 représente :","r":["une hyperbole","une ellipse","une parabole","un cercle"],"b":1,"e":"Somme de deux carrés positifs égale à 1."},{"q":"L'équation x²/9 − y²/4 = 1 représente :","r":["une ellipse","une parabole","une hyperbole","un cercle"],"b":2,"e":"Différence de deux carrés."},{"q":"L'équation y² = 4x représente :","r":["une ellipse","une hyperbole","une droite","une parabole"],"b":3,"e":"Une seule variable est au carré."}],"c":"Tle C","m":"maths","rang":48,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un technicien de télévision à Bafia oriente une antenne parabolique sur un toit.","tache":"Explique où placer le récepteur."},"gratuit":true});
VRT_L("tle-c-maths-r49",{"duree":20,"titre":"Définition monofocale des coniques","accroche":"Un point, une droite, un rapport constant.","intro":"Une seule définition suffit à décrire les trois coniques.","objectifs":["énoncer la définition","identifier selon e","calculer un paramètre"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Soit F un point, D une droite et e > 0. La <strong>conique</strong> de foyer F, de directrice D et d'<strong>excentricité e</strong> est l'ensemble des points M tels que <strong>MF = e × d(M ; D)</strong>.</div>"},{"t":"Selon e","verrou":true},{"t":"Le paramètre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":49,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un projet d'astronomie au lycée de Buea, on étudie une trajectoire d'excentricité 0,2.","tache":"Donne la nature de la trajectoire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r50",{"duree":25,"titre":"Définition analytique et construction des coniques","accroche":"Une équation réduite, et la courbe se dessine.","intro":"Dans un repère bien choisi, les coniques ont des équations simples.","objectifs":["reconnaître une équation réduite","trouver foyers et sommets","tracer une conique"],"parties":[{"t":"Équations réduites","html":"<div class='def'><b>Équations réduites</b>Ellipse : <strong>x²/a² + y²/b² = 1</strong>. Hyperbole : <strong>x²/a² − y²/b² = 1</strong>. Parabole : <strong>y² = 2px</strong>.</div>"},{"t":"Éléments","verrou":true},{"t":"Construction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":50,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un jardinier de Dschang veut tracer un massif elliptique de grand axe 10 m et petit axe 6 m avec une corde.","tache":"Place les foyers."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r51",{"duree":20,"titre":"Tangente à une conique","accroche":"Une tangente obtenue par dédoublement des termes.","intro":"L'équation de la tangente en un point se déduit directement de l'équation réduite.","objectifs":["écrire une équation de tangente","vérifier le point","utiliser la tangente"],"parties":[{"t":"Formules","html":"<div class='def'><b>Tangente en M₀(x₀ ; y₀)</b>Ellipse : <strong>xx₀/a² + yy₀/b² = 1</strong>. Hyperbole : <strong>xx₀/a² − yy₀/b² = 1</strong>. Parabole : <strong>yy₀ = p(x + x₀)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Propriété de réflexion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":51,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une réflexion lumineuse dans un miroir parabolique d'un projet solaire à Maroua concentre les rayons en un point.","tache":"Indique ce point."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r52",{"duree":20,"titre":"Similitudes directes et coniques","accroche":"Une similitude ne change pas la nature d'une conique.","intro":"Les transformations du plan permettent de déduire des coniques à partir d'autres.","objectifs":["déterminer l'image d'une conique","utiliser l'excentricité","appliquer à un exercice"],"parties":[{"t":"Propriété","html":"<div class='def'><b>Propriété</b>L'image d'une conique d'excentricité e par une <strong>similitude directe</strong> est une conique de <strong>même excentricité</strong>.</div>"},{"t":"Éléments transformés","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":52,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un plan d'antenne est agrandi deux fois sur une maquette du lycée technique de Douala.","tache":"Dis si la forme de la parabole change."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r58",{"duree":20,"titre":"Réflexions de l'espace","accroche":"Un miroir plan, en mathématiques.","intro":"La réflexion par rapport à un plan est une isométrie de l'espace.","objectifs":["définir une réflexion","construire une image","citer ses propriétés"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>réflexion de plan P</strong> associe à tout point M le point M' tel que P soit le plan médiateur de [MM'].</div>"},{"t":"Propriétés","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":58,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un architecte d'intérieur à Douala veut placer l'image d'une lampe dans un grand miroir mural.","tache":"Indique comment déterminer l'image."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r59",{"duree":20,"titre":"Les demi-tours","accroche":"Tourner de 180° autour d'une droite.","intro":"Un demi-tour est une rotation d'angle π autour d'un axe. Il se décompose en deux réflexions.","objectifs":["définir un demi-tour","décomposer en réflexions","calculer une image"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>demi-tour d'axe D</strong> est la transformation qui associe à M le point M' tel que D soit la médiatrice de [MM'], M' étant dans le plan perpendiculaire à D passant par M.</div>"},{"t":"Décomposition","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":59,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un engin de levage sur le port de Kribi fait pivoter une charge d'un demi-tour autour d'un axe vertical.","tache":"Donne l'image d'un point (1 ; 2 ; 3) si l'axe est (Oz)."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r01",{"duree":20,"titre":"Les alcools et le sodium","accroche":"Une réaction vive, qui révèle l'hydrogène mobile de l'alcool.","intro":"Le groupe hydroxyle des alcools réagit avec le sodium, comme le fait l'eau, mais plus doucement.","objectifs":["écrire l'équation de la réaction","identifier le gaz dégagé","nommer l'alcoolate formé"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>Un <strong>alcool</strong> possède un groupe hydroxyle −OH porté par un carbone tétragonal. Il réagit avec le sodium en libérant du dihydrogène et en formant un <strong>alcoolate</strong> : <strong>2 R−OH + 2 Na → 2 (R−O⁻ + Na⁺) + H₂</strong>.</div>"},{"t":"Mise en évidence","html":"<p>Le dihydrogène détone à l'approche d'une flamme. L'alcoolate donne une solution basique.</p><div class='ex'><b>Exemple</b>Avec l'éthanol, on forme l'éthanolate de sodium.</div>","labo":{"type":"equilibre","reactifs":[{"f":"C₂H₅OH","at":{"C":2,"H":6,"O":1}},{"f":"Na","at":{"Na":1}}],"produits":[{"f":"C₂H₅ONa","at":{"C":2,"H":5,"O":1,"Na":1}},{"f":"H₂","at":{"H":2}}]}},{"t":"Sécurité","html":"<div class='attention'><b>Sécurité</b>Le sodium réagit violemment avec l'eau : il se manipule en petite quantité, sous la conduite du professeur.</div>","retenir":"Un alcoolate est une base forte."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Le groupe caractéristique des alcools est :</p><ol type='a'><li>le groupe carbonyle C=O porté par un carbone trigonal</li><li>le groupe hydroxyle −OH porté par un carbone tétragonal</li><li>le groupe carboxyle −COOH porté par un carbone terminal</li><li>le groupe amine −NH₂ porté par un carbone tétragonal</li></ol><details><summary>Voir la réponse</summary><p><strong>le groupe hydroxyle −OH porté par un carbone tétragonal</strong>. Le carbone qui porte −OH n'est lié qu'à des atomes par liaisons simples.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Quel volume de H₂ (CNTP) se forme avec 0,2 mol d'éthanol ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 0,1 mol, soit 2,24 L.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Au laboratoire d'un lycée de Bafoussam, un flacon contient un monoalcool saturé inconnu. On fait réagir 2,3 g de cet alcool avec un excès de sodium : il se dégage 0,56 L de dihydrogène (volume molaire 22,4 L/mol). Akono affirme qu'il s'agit du propan-1-ol ; Bella, de l'éthanol. M(C) = 12 ; M(H) = 1 ; M(O) = 16 g/mol.</p><p><strong>Consigne 1.</strong> Écris l'équation de la réaction de l'alcool sur le sodium.</p><p><strong>Consigne 2.</strong> À l'aide d'une démarche scientifique, départage Akono et Bella.</p><details><summary>Voir une réponse attendue</summary><p>2 R-OH + 2 Na → 2 R-O⁻ + 2 Na⁺ + H₂. n(H₂) = 0,56/22,4 = 0,025 mol, donc n(alcool) = 0,05 mol et M = 2,3/0,05 = 46 g/mol. CₙH₂ₙ₊₁OH : 14n + 18 = 46, n = 2 : c'est l'éthanol. Bella a raison.</p></details></div>","retenir":"Savoir-être mobilisé : Souci de la sécurité au laboratoire."}],"revision":["R−OH + Na : alcoolate + H₂.","Test du H₂ : détonation."],"exo":"<p>Quel volume de H₂ (CNTP) se forme avec 0,2 mol d'éthanol ? <em>(Réponse : 0,1 mol, soit 2,24 L.)</em></p>","quiz":[{"q":"Le groupe caractéristique des alcools est :","r":["le groupe carbonyle C=O porté par un carbone trigonal","le groupe hydroxyle −OH porté par un carbone tétragonal","le groupe carboxyle −COOH porté par un carbone terminal","le groupe amine −NH₂ porté par un carbone tétragonal"],"b":1,"e":"Le carbone qui porte −OH n'est lié qu'à des atomes par liaisons simples."},{"q":"La formule générale des alcools saturés non cycliques est :","r":["CₙH₂ₙO₂","CₙH₂ₙ","CₙH₂ₙ₊₁OH","CₙH₂ₙ₊₂"],"b":2,"e":"Ex. : C₂H₅OH, l'éthanol."},{"q":"Le propan-2-ol est un alcool :","r":["primaire","tertiaire","aromatique","secondaire"],"b":3,"e":"Le carbone fonctionnel est lié à deux atomes de carbone."},{"q":"Le 2-méthylpropan-2-ol est un alcool :","r":["tertiaire","primaire","secondaire","phénolique"],"b":0,"e":"Le carbone fonctionnel est lié à trois atomes de carbone."},{"q":"Le sodium réagit avec un alcool en donnant :","r":["un ester et de l'eau, de façon limitée","un alcoolate et du dihydrogène","un aldéhyde et du dihydrogène","un alcène, de l'eau et du dioxygène gazeux"],"b":1,"e":"2 R−OH + 2 Na → 2 R−O⁻ + 2 Na⁺ + H₂."},{"q":"Le gaz dégagé par l'action du sodium sur l'éthanol :","r":["trouble l'eau de chaux en formant un précipité","ravive une bûchette qui présente un point incandescent","produit une légère détonation à la flamme","est incolore, inodore et ne réagit pas à la flamme"],"b":2,"e":"C'est le test du dihydrogène."},{"q":"Le nom de CH₃−CH₂−CH₂−OH est :","r":["propan-2-ol","éthanol","butan-1-ol","propan-1-ol"],"b":3,"e":"La chaîne a trois carbones et −OH sur le carbone 1."},{"q":"L'ion éthanolate C₂H₅O⁻ est :","r":["une base forte","un acide fort","un oxydant","un sel neutre"],"b":0,"e":"Il réagit totalement avec l'eau."},{"q":"La réaction du sodium avec l'éthanol est moins vive qu'avec l'eau car :","r":["l'éthanol est un acide plus fort que l'eau","l'éthanol est un acide plus faible que l'eau","le sodium ne réagit pas avec l'éthanol, contrairement à l'eau","l'éthanol est un gaz à la température ordinaire"],"b":1,"e":"La liaison O−H de l'éthanol est moins polarisée."},{"q":"Les alcools ont des températures d'ébullition élevées en raison :","r":["de leur masse molaire très élevée","de leur couleur et de leur odeur","des liaisons hydrogène entre molécules","de l'absence de toute liaison entre molécules"],"b":2,"e":"Le groupe −OH crée des liaisons hydrogène."}],"c":"Tle C","m":"chimie","rang":1,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un laborantin d'un lycée de Bafoussam doit vérifier si un flacon non étiqueté contient un alcool.","tache":"Propose un test et écris l'équation avec l'éthanol."},"gratuit":true});
VRT_L("tle-c-chimie-r02",{"duree":20,"titre":"La déshydratation des alcools","accroche":"Selon la température, on obtient un alcène ou un éther.","intro":"En retirant de l'eau, l'alcool se transforme. La température décide du produit.","objectifs":["distinguer déshydratations intra et intermoléculaire","écrire les équations","prévoir le produit"],"parties":[{"t":"Déshydratation intramoléculaire","html":"<div class='def'><b>Définition</b>La <strong>déshydratation intramoléculaire</strong> élimine une molécule d'eau à partir d'une molécule d'alcool, et forme un <strong>alcène</strong>.</div><p class='formule'>CH₃−CH₂OH → CH₂=CH₂ + H₂O (vers 170 °C, en milieu acide)</p>"},{"t":"Déshydratation intermoléculaire","verrou":true},{"t":"Choisir les conditions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":2,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un technicien de Douala dispose d'éthanol et doit obtenir de l'éthène pour une synthèse.","tache":"Indique les conditions à choisir."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r03",{"duree":25,"titre":"L'oxydation des alcools","accroche":"Le vin de palme qui tourne au vinaigre : une oxydation ménagée.","intro":"La classe d'un alcool détermine le produit de son oxydation. Cette question revient très souvent au bac.","objectifs":["définir l'oxydation ménagée","prévoir le produit selon la classe","identifier un aldéhyde et une cétone"],"parties":[{"t":"Combustion et oxydation ménagée","html":"<div class='def'><b>Définition</b>L'<strong>oxydation ménagée</strong> est une oxydation qui s'effectue sans destruction de la chaîne carbonée. La combustion, elle, la détruit.</div>"},{"t":"Selon la classe","verrou":true},{"t":"Les tests","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":3,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une vendeuse de vin de palme à Bafia remarque que sa boisson devient acide au bout de quelques jours.","tache":"Explique la transformation de l'éthanol."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r04",{"duree":25,"titre":"L'estérification","accroche":"Lente, limitée, athermique : les trois mots du bac.","intro":"Un acide et un alcool forment un ester et de l'eau. Le rendement dépend de la classe de l'alcool.","objectifs":["écrire la réaction","citer ses caractéristiques","améliorer le rendement"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>L'<strong>estérification</strong> est la réaction entre un acide carboxylique et un alcool, formant un <strong>ester</strong> et de l'eau : <strong>R−COOH + R'−OH ⇌ R−COO−R' + H₂O</strong>.</div><p>La formule générale d'un ester saturé est CₙH₂ₙO₂.</p>"},{"t":"Caractéristiques","verrou":true},{"t":"Améliorer le rendement","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":4,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un artisan de Limbé fabrique un arôme fruité à partir d'acide éthanoïque et d'éthanol, mais il trouve son rendement trop faible.","tache":"Propose deux moyens de l'améliorer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r05",{"duree":20,"titre":"Préparation des alcools","accroche":"Du maïs à l'alcool : la fermentation.","intro":"Les alcools s'obtiennent à partir d'alcènes ou par fermentation. Une boisson mal distillée peut être mortelle.","objectifs":["écrire l'hydratation d'un alcène","appliquer la règle de Markovnikov","écrire la fermentation"],"parties":[{"t":"Hydratation d'un alcène","html":"<div class='def'><b>Définition</b>L'<strong>hydratation d'un alcène</strong> fixe une molécule d'eau sur la double liaison et forme un alcool.</div><p>Règle de Markovnikov : l'hydrogène se fixe de préférence sur le carbone le plus hydrogéné.</p>"},{"t":"Fermentation alcoolique","verrou":true},{"t":"Danger du méthanol","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":5,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Dans un village de l'Extrême-Nord, une famille prépare du bili-bili à partir de sorgho.","tache":"Écris l'équation de la fermentation du glucose et calcule la quantité d'éthanol obtenue avec 2 mol de glucose."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r06",{"duree":20,"titre":"Les acides carboxyliques : structure et nomenclature","accroche":"Le goût piquant du vinaigre vient d'un groupe précis.","intro":"Les acides carboxyliques portent un groupe carboxyle. Ils se nomment à partir de la chaîne la plus longue.","objectifs":["reconnaître le groupe carboxyle","nommer un acide","citer des propriétés physiques"],"parties":[{"t":"Structure","html":"<div class='def'><b>Définition</b>Un <strong>acide carboxylique</strong> possède le groupe carboxyle <strong>−COOH</strong>. Sa formule générale saturée est CₙH₂ₙO₂.</div>"},{"t":"Nomenclature","verrou":true},{"t":"Propriétés physiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":6,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un élève de Kumba doit identifier le composant du vinaigre d'un flacon.","tache":"Donne sa formule et son nom systématique."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r07",{"duree":25,"titre":"Acides carboxyliques : chlorures d'acyle et anhydrides","accroche":"Des dérivés bien plus réactifs que l'acide.","intro":"Les acides carboxyliques sont des acides faibles. Leurs dérivés permettent des synthèses efficaces, dont celle de l'aspirine.","objectifs":["écrire la dissociation d'un acide","préparer un chlorure d'acyle","former un anhydride"],"parties":[{"t":"Propriétés acides","html":"<div class='def'><b>Définition</b>Un <strong>acide faible</strong> ne réagit que partiellement avec l'eau : <strong>R−COOH + H₂O ⇌ R−COO⁻ + H₃O⁺</strong>.</div>"},{"t":"Chlorures d'acyle","verrou":true},{"t":"Anhydrides","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":7,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Dans un laboratoire pharmaceutique de Yaoundé, on veut préparer de l'aspirine avec un excellent rendement.","tache":"Explique pourquoi on choisit l'anhydride éthanoïque plutôt que l'acide éthanoïque."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r08",{"duree":25,"titre":"Amides, polycondensation et saponification","accroche":"L'huile de palme et la soude donnent du savon.","intro":"Les dérivés d'acides conduisent aux amides, aux polyamides et aux savons, très présents dans notre quotidien.","objectifs":["former un amide","définir la polycondensation","écrire la saponification"],"parties":[{"t":"Les amides","html":"<div class='def'><b>Définition</b>Un <strong>amide</strong> contient le groupe −CO−N&lt;. On l'obtient en faisant réagir une amine ou l'ammoniac avec un chlorure d'acyle ou un anhydride.</div>"},{"t":"Polycondensation","verrou":true},{"t":"La saponification","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":8,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une coopérative de femmes à Mbanga fabrique du savon à partir d'huile de palme et de soude.","tache":"Écris le principe de la réaction et dis pourquoi elle est préférable à une réaction réversible."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r09",{"duree":20,"titre":"Les amines : généralités","accroche":"L'odeur du poisson a une origine chimique.","intro":"Les amines dérivent de l'ammoniac. Leur classe dépend du nombre de groupes fixés sur l'azote.","objectifs":["reconnaître une amine","donner sa classe","nommer une amine"],"parties":[{"t":"Définition et classe","html":"<div class='def'><b>Définition</b>Une <strong>amine</strong> dérive de NH₃ par remplacement d'atomes d'hydrogène par des groupes carbonés. Elle est <strong>primaire</strong>, <strong>secondaire</strong> ou <strong>tertiaire</strong>.</div>"},{"t":"Nomenclature","verrou":true},{"t":"Propriétés physiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":9,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une technicienne de Kribi analyse les composés responsables de l'odeur du poisson au port.","tache":"Classe la triméthylamine."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r10",{"duree":20,"titre":"Propriétés chimiques des amines","accroche":"Un doublet libre, et l'amine devient base et nucléophile.","intro":"Le doublet non liant de l'azote explique le caractère basique et nucléophile des amines.","objectifs":["expliquer le caractère basique","écrire l'alkylation","écrire l'acylation"],"parties":[{"t":"Caractère basique","html":"<div class='def'><b>Propriété</b>Grâce au doublet libre de l'azote, une amine est une <strong>base faible</strong> : <strong>R−NH₂ + H₂O ⇌ R−NH₃⁺ + HO⁻</strong>.</div>"},{"t":"Alkylation","verrou":true},{"t":"Acylation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":10,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une équipe de contrôle de Douala teste un produit de nettoyage contenant une amine.","tache":"Écris sa réaction avec l'eau et le caractère de la solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r11",{"duree":20,"titre":"Acides α-aminés","accroche":"Les briques de toutes nos protéines.","intro":"Les acides α-aminés portent deux fonctions qui leur donnent une propriété originale, l'ion dipolaire.","objectifs":["reconnaître un acide α-aminé","écrire l'amphion","connaître la configuration naturelle"],"parties":[{"t":"Structure","html":"<div class='def'><b>Définition</b>Un <strong>acide α-aminé</strong> possède un groupe carboxyle et un groupe amino portés par le même carbone : <strong>R−CH(NH₂)−COOH</strong>.</div>"},{"t":"L'amphion","verrou":true},{"t":"Chiralité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":11,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Une nutritionniste de Maroua explique que les protéines du niébé sont formées d'acides aminés.","tache":"Écris la forme dipolaire de l'alanine."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r12",{"duree":25,"titre":"La synthèse des polypeptides","accroche":"Une liaison répétée construit une protéine.","intro":"La liaison peptidique unit deux acides α-aminés. Une synthèse contrôlée suppose de protéger certaines fonctions.","objectifs":["écrire une liaison peptidique","compter les dipeptides","décrire le blocage et l'activation"],"parties":[{"t":"La liaison peptidique","html":"<div class='def'><b>Définition</b>La <strong>liaison peptidique</strong> −CO−NH− résulte de la condensation du groupe carboxyle d'un acide α-aminé sur le groupe amino d'un autre.</div>"},{"t":"Les dipeptides possibles","verrou":true},{"t":"La synthèse contrôlée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":12,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un laboratoire de recherche à Yaoundé veut fabriquer uniquement le dipeptide Gly-Ala.","tache":"Présente les étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r13",{"duree":15,"titre":"L'isomérie de constitution","accroche":"Mêmes atomes, liens différents, propriétés différentes.","intro":"Des composés de même formule brute peuvent être très différents.","objectifs":["définir l'isomérie","distinguer les trois types","écrire des isomères"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Des <strong>isomères de constitution</strong> ont la même formule brute, mais un enchaînement d'atomes différent.</div>"},{"t":"Les types","html":"<ul><li>De chaîne.</li><li>De position.</li><li>De fonction.</li></ul>","labo":{"type":"trier","invite":"Choisis un type.","items":[["De chaîne","squelette différent."],["De position","groupe fonctionnel déplacé."],["De fonction","groupe fonctionnel différent."]]}},{"t":"Exemple","html":"<p>C₂H₆O : éthanol CH₃−CH₂OH et méthoxyméthane CH₃−O−CH₃ sont isomères de fonction.</p>","retenir":"Même formule brute, formules développées différentes."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Des isomères ont :</p><ol type='a'><li>la même formule développée et des formules brutes différentes</li><li>des masses molaires différentes</li><li>la même formule brute et des formules développées différentes</li><li>des formules brutes différentes et la même fonction</li></ol><details><summary>Voir la réponse</summary><p><strong>la même formule brute et des formules développées différentes</strong>. Ils ont des propriétés différentes.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Butan-1-ol et butan-2-ol : quel type d'isomérie ?</p><details><summary>Voir la réponse</summary><p>(Réponse : de position.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Lors d'un bac blanc, on demande tous les isomères de formule C₄H₁₀O. Un élève en trouve quatre ; un autre affirme qu'il y en a sept.</p><p><strong>Consigne 1.</strong> Écris les formules semi-développées et nomme tous les isomères.</p><p><strong>Consigne 2.</strong> Départage les deux élèves en précisant les types d'isomérie.</p><details><summary>Voir une réponse attendue</summary><p>Alcools : butan-1-ol, butan-2-ol, 2-méthylpropan-1-ol, 2-méthylpropan-2-ol. Éthers : méthoxypropane, 2-méthoxypropane, éthoxyéthane. Sept isomères : isomérie de chaîne, de position et de fonction (alcool/éther). Le second élève a raison.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche expérimentale."}],"revision":["Même formule brute.","Chaîne, position, fonction."],"exo":"<p>Butan-1-ol et butan-2-ol : quel type d'isomérie ? <em>(Réponse : de position.)</em></p>","quiz":[{"q":"Des isomères ont :","r":["la même formule développée et des formules brutes différentes","des masses molaires différentes","la même formule brute et des formules développées différentes","des formules brutes différentes et la même fonction"],"b":2,"e":"Ils ont des propriétés différentes."},{"q":"Le butane et le méthylpropane sont des isomères :","r":["de fonction","de position","optiques","de chaîne"],"b":3,"e":"Ils diffèrent par la structure de la chaîne carbonée."},{"q":"Le propan-1-ol et le propan-2-ol sont des isomères :","r":["de position","de chaîne","de fonction","géométriques"],"b":0,"e":"Le groupe OH n'est pas sur le même carbone."},{"q":"L'éthanol et le méthoxyméthane sont des isomères :","r":["de position","de fonction","de chaîne","optiques"],"b":1,"e":"Ils ont la formule C₂H₆O mais des fonctions différentes."},{"q":"Le propanal et la propanone sont des isomères :","r":["de chaîne","géométriques","de fonction","optiques"],"b":2,"e":"Aldéhyde et cétone de formule C₃H₆O."},{"q":"Le nombre d'isomères de formule C₄H₁₀ est :","r":["1","3","4","2"],"b":3,"e":"Le butane et le méthylpropane."},{"q":"L'isomérie de constitution concerne :","r":["l'enchaînement des atomes","l'orientation dans l'espace seulement","la couleur","l'état physique"],"b":0,"e":"Les atomes sont liés différemment."},{"q":"Le nombre d'alcools isomères de formule C₃H₈O est :","r":["1","2","3","4"],"b":1,"e":"Propan-1-ol et propan-2-ol."},{"q":"Les isomères de fonction ont :","r":["les mêmes propriétés chimiques et la même fonction","la même fonction chimique","des propriétés chimiques différentes","la même formule développée plane"],"b":2,"e":"Leurs groupes caractéristiques diffèrent."},{"q":"La formule C₂H₄O₂ peut correspondre à :","r":["l'éthanol ou l'éthanal, son produit d'oxydation","l'éthène","l'éthanal","l'acide éthanoïque ou le méthanoate de méthyle"],"b":3,"e":"Acide et ester sont isomères de fonction."}],"c":"Tle C","m":"chimie","rang":13,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Deux flacons d'un laboratoire de Dschang portent la même formule C₄H₁₀O. Le liquide A réagit avec le sodium (dégagement gazeux) et bout à 118 °C ; le liquide B ne réagit pas avec le sodium et bout à 35 °C.","tache":"Explique ce qui les distingue et propose une formule pour chacun."},"gratuit":true});
VRT_L("tle-c-chimie-r14",{"duree":25,"titre":"La stéréo-isomérie","accroche":"Deux molécules comme une main droite et une main gauche.","intro":"Des molécules de même enchaînement peuvent différer par leur disposition dans l'espace.","objectifs":["distinguer Z et E","reconnaître un carbone asymétrique","représenter des énantiomères"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Des <strong>stéréo-isomères</strong> ont le même enchaînement d'atomes, mais une disposition différente dans l'espace.</div>"},{"t":"Isomérie Z/E","verrou":true},{"t":"Énantiomérie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":14,"apc":{"module":"Chimie organique","famille":"Usage des composés organiques dans la vie courante","agir":"Identifier, nommer et transformer des composés organiques","situation":"Un parfumeur de Douala reçoit deux échantillons d'un arôme, le 2-méthylbutan-1-ol, qui dévient la lumière polarisée en sens opposés. Son assistant pense qu'il s'agit d'une erreur de mesure.","tache":"Montre que la molécule est chirale en identifiant le carbone concerné et réponds à l'assistant."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r15",{"duree":25,"titre":"Évolution d'un système et vitesse de réaction","accroche":"Une vitesse se lit sur une tangente.","intro":"La cinétique étudie la rapidité des réactions. Elle est au programme du bac sous forme de graphiques.","objectifs":["définir réaction rapide et lente","calculer une vitesse","relier les vitesses à l'équation"],"parties":[{"t":"Réactions rapides et lentes","html":"<div class='def'><b>Définitions</b>Une <strong>réaction rapide</strong> paraît achevée dès que les réactifs sont mis en contact. Une <strong>réaction lente</strong> dure de quelques secondes à plusieurs heures.</div>"},{"t":"Vitesse instantanée","verrou":true},{"t":"Suivre une réaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":15,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Au laboratoire d'un lycée de Bafoussam, on suit la formation de diiode en prélevant des échantillons toutes les 5 minutes.","tache":"Explique pourquoi on plonge chaque prélèvement dans la glace."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r16",{"duree":20,"titre":"Les facteurs cinétiques","accroche":"Pourquoi les aliments se gardent mieux au froid.","intro":"La température, la concentration et le catalyseur modifient la vitesse des réactions.","objectifs":["définir un facteur cinétique","citer les facteurs","définir un catalyseur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>facteur cinétique</strong> est un paramètre qui modifie la vitesse d'une réaction : température, concentration, catalyseur.</div>"},{"t":"Influence","verrou":true},{"t":"Le catalyseur","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":16,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une vendeuse de Ngaoundéré conserve sa viande dans la glace pour la vendre le lendemain.","tache":"Explique l'effet du froid sur les réactions de dégradation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r17",{"duree":20,"titre":"L'eau, l'autoprotolyse et le pH","accroche":"Une eau neutre n'a pas toujours un pH de 7.","intro":"L'eau pure contient un peu d'ions. Leur produit dépend de la température.","objectifs":["écrire l'autoprotolyse","utiliser Ke","calculer un pH neutre"],"parties":[{"t":"Autoprotolyse","html":"<div class='def'><b>Définition</b>L'<strong>autoprotolyse</strong> de l'eau est la réaction : <strong>2 H₂O ⇌ H₃O⁺ + HO⁻</strong>. Le produit ionique est <strong>Ke = [H₃O⁺][HO⁻]</strong>, soit 10⁻¹⁴ à 25 °C.</div>"},{"t":"pH","verrou":true},{"t":"Effet de la température","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":17,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un technicien d'hôpital à Douala s'étonne qu'une solution neutre à 37 °C n'ait pas un pH de 7.","tache":"Explique ce fait avec pKe = 13,72."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r18",{"duree":15,"titre":"Les acides forts","accroche":"Une réaction totale avec l'eau.","intro":"Le pH d'un acide fort se calcule directement à partir de sa concentration.","objectifs":["définir un acide fort","calculer un pH","écrire l'équation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Selon Brönsted, un <strong>acide</strong> est une espèce capable de céder un proton. Un <strong>acide fort</strong> réagit totalement avec l'eau.</div><p class='formule'>HCl + H₂O → H₃O⁺ + Cl⁻</p>"},{"t":"Le pH","verrou":true},{"t":"Dilution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":18,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un technicien d'une usine de Bassa, à Douala, doit vérifier une solution d'acide chlorhydrique étiquetée à 0,01 mol/L.","tache":"Dis quel pH il devrait mesurer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r19",{"duree":15,"titre":"Les bases fortes","accroche":"De la soude à l'eau de Javel, attention au pH élevé.","intro":"Le pH d'une base forte se calcule à partir de sa concentration et de Ke.","objectifs":["définir une base forte","calculer un pH","manipuler avec prudence"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Selon Brönsted, une <strong>base</strong> est une espèce capable de capter un proton. Une <strong>base forte</strong> réagit totalement avec l'eau.</div>"},{"t":"Le pH","verrou":true},{"t":"Sécurité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":19,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une savonnerie artisanale de Mbanga utilise une solution de soude à 0,1 mol/L.","tache":"Calcule son pH et indique la protection nécessaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r20",{"duree":25,"titre":"Acides faibles et bases faibles","accroche":"Une réaction limitée, plusieurs espèces à calculer.","intro":"Un acide faible coexiste avec sa base conjuguée. Les bac réclament l'inventaire complet des concentrations.","objectifs":["faire l'inventaire des espèces","écrire électroneutralité et conservation","calculer une concentration"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>acide faible</strong> réagit partiellement avec l'eau : <strong>AH + H₂O ⇌ A⁻ + H₃O⁺</strong>.</div>"},{"t":"Méthode du bac","verrou":true},{"t":"Comparer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":20,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un flacon de jus de citron analysé à Bafoussam présente un pH plus élevé que celui d'un acide fort de même concentration.","tache":"Conclus sur la nature de l'acide."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r21",{"duree":25,"titre":"Couples acide/base et domaines de prédominance","accroche":"pH = pKa : les deux formes sont à égalité.","intro":"Le pKa indique la force d'un acide et permet de prévoir quelle forme domine.","objectifs":["définir Ka et pKa","appliquer la relation d'Henderson","tracer un domaine de prédominance"],"parties":[{"t":"Constante d'acidité","html":"<div class='def'><b>Définition</b>Pour un couple AH/A⁻ : <strong>Ka = [A⁻][H₃O⁺] / [AH]</strong> et <strong>pKa = −log Ka</strong>.</div>"},{"t":"La relation","verrou":true},{"t":"Prédominance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":21,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Pour contrôler un flacon, un élève de Limbé compare son pKa calculé (4,2) à un tableau de pKa d'acides connus.","tache":"Explique comment identifier l'acide."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r22",{"duree":25,"titre":"Dosage acide fort - base forte","accroche":"Trois zones, un saut de pH, et un calcul simple.","intro":"Un dosage détermine une concentration inconnue. La courbe présente une forme caractéristique.","objectifs":["écrire la réaction de dosage","déterminer l'équivalence","calculer une concentration"],"parties":[{"t":"Le dosage","html":"<div class='def'><b>Définition</b>Un <strong>dosage</strong> détermine la concentration d'une solution à l'aide d'une réaction totale. À l'<strong>équivalence</strong>, les réactifs sont dans les proportions stœchiométriques.</div><p class='formule'>H₃O⁺ + HO⁻ → 2 H₂O</p>"},{"t":"Équivalence","html":"<p class='formule'>C_a V_a = C_b V_bE</p><p>Pour un dosage acide fort - base forte à 25 °C, le pH à l'équivalence vaut 7.</p>","labo":{"type":"dosage","mode":"fort"}},{"t":"Trouver le point","html":"<p>La méthode des tangentes parallèles donne le point d'équivalence. Un indicateur coloré dont la zone de virage contient pH 7 convient.</p>","retenir":"À l'équivalence : C_a V_a = C_b V_bE."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Au cours du dosage d'un acide fort par une base forte, à l'équivalence :</p><ol type='a'><li>le pH vaut 7 à 25 °C</li><li>le pH vaut 4,0</li><li>le pH vaut 10,0 à toute température</li><li>le pH vaut 0</li></ol><details><summary>Voir la réponse</summary><p><strong>le pH vaut 7 à 25 °C</strong>. La solution ne contient que de l'eau et un sel neutre.</p></details><p><strong>Application directe des savoirs.</strong></p><p>V_a = 20 mL, C_b = 0,1 mol/L, V_bE = 10 mL : C_a ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 0,05 mol/L.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un détartrant est une solution concentrée d'acide chlorhydrique. On la dilue 10 fois ; 10 mL de solution diluée sont dosés par une soude à 0,10 mol/L : Véq = 12 mL. L'étiquette indique 1,0 mol/L.</p><p><strong>Consigne 1.</strong> Écris l'équation du dosage et calcule la concentration du détartrant.</p><p><strong>Consigne 2.</strong> L'étiquette est-elle exacte ? Quel indicateur coloré utiliser ?</p><details><summary>Voir une réponse attendue</summary><p>H₃O⁺ + HO⁻ → 2 H₂O. C(diluée) = 0,10 × 12/10 = 0,12 mol/L ; C = 1,2 mol/L. L'étiquette est inexacte : la solution est plus concentrée que les 1,0 mol/L annoncés (écart de 20 % par rapport à l'étiquette). Équivalence à pH 7 : bleu de bromothymol.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["Réaction totale.","C_a V_a = C_b V_bE.","pH = 7."],"exo":"<p>V_a = 20 mL, C_b = 0,1 mol/L, V_bE = 10 mL : C_a ? <em>(Réponse : 0,05 mol/L.)</em></p>","quiz":[{"q":"Au cours du dosage d'un acide fort par une base forte, à l'équivalence :","r":["le pH vaut 7 à 25 °C","le pH vaut 4,0","le pH vaut 10,0 à toute température","le pH vaut 0"],"b":0,"e":"La solution ne contient que de l'eau et un sel neutre."},{"q":"À l'équivalence, on a :","r":["Ca = Cb","Ca Va = Cb VbE","Va = VbE toujours","Ca Vb = Cb Va"],"b":1,"e":"Les quantités d'acide et de base apportées sont égales."},{"q":"10 mL d'acide chlorhydrique sont dosés par de la soude à 0,1 mol/L ; VbE = 15 mL. Ca vaut :","r":["0,1 mol/L","0,067 mol/L","0,15 mol/L","1,5 mol/L"],"b":2,"e":"Ca = 0,1 × 15/10."},{"q":"La courbe pH = f(Vb) d'un dosage acide fort-base forte présente :","r":["une droite croissante, sans aucun saut","aucun saut de pH","un pH constant","un saut de pH important autour de l'équivalence"],"b":3,"e":"Le pH passe brusquement de 4 à 10 environ."},{"q":"L'équivalence se repère graphiquement par :","r":["la méthode des tangentes parallèles","le premier point de la courbe de dosage","le dernier point de la courbe","l'origine des axes"],"b":0,"e":"On trace deux tangentes parallèles et leur médiane."},{"q":"Un indicateur convenable pour ce dosage est :","r":["l'hélianthine seule, toujours (virage 3,1-4,4)","le bleu de bromothymol (virage 6,0-7,6)","aucun","l'eau iodée"],"b":1,"e":"Sa zone de virage contient le pH à l'équivalence."},{"q":"La réaction de dosage s'écrit :","r":["H₃O⁺ + Cl⁻ → HCl","Na⁺ + Cl⁻ → NaCl","H₃O⁺ + HO⁻ → 2 H₂O","H₂O → H⁺ + HO⁻"],"b":2,"e":"C'est une réaction totale et rapide."},{"q":"Avant l'équivalence, le réactif en excès est :","r":["la base","l'eau","aucun","l'acide"],"b":3,"e":"La base versée est entièrement consommée."},{"q":"On utilise pour verser la solution titrante :","r":["une burette graduée","un bécher","une éprouvette non graduée","une pipette jaugée"],"b":0,"e":"Elle permet de lire le volume versé."},{"q":"Un dosage conductimétrique se repère par :","r":["un changement de couleur de la solution titrée","un changement de pente de la conductance","un pH de 7 exactement","aucun signal mesurable"],"b":1,"e":"Les ions remplacés ont des conductivités différentes."}],"c":"Tle C","m":"chimie","rang":22,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Un lycée de Douala reçoit un lot d'acide chlorhydrique étiqueté 0,1 mol/L. Deux élèves veulent vérifier le titre.","tache":"20 mL d'acide nécessitent 20 mL de soude à 0,1 mol/L. Conclus."},"gratuit":true});
VRT_L("tle-c-chimie-r23",{"duree":25,"titre":"Dosage acide faible - base forte","accroche":"À la demi-équivalence, la courbe donne le pKa.","intro":"Ce dosage est le plus fréquent aux examens. La courbe révèle à la fois la concentration et le pKa.","objectifs":["décrire la courbe","déterminer la concentration","lire le pKa"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>La réaction de dosage est totale : <strong>AH + HO⁻ → A⁻ + H₂O</strong>. À l'équivalence, le pH est <strong>supérieur à 7</strong>.</div>"},{"t":"La demi-équivalence","verrou":true},{"t":"Exploiter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":23,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Des sachets d'aspirine reçus par une infirmerie scolaire sont étiquetés 100 mg. Deux élèves veulent vérifier la masse réelle.","tache":"Explique comment un dosage acide-base permet de vérifier l'étiquette."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r24",{"duree":25,"titre":"Dosage base faible - acide fort","accroche":"Une courbe descendante, le même raisonnement.","intro":"Le dosage d'une base faible par un acide fort s'analyse comme celui d'un acide faible.","objectifs":["écrire la réaction","déterminer l'équivalence","lire le pKa"],"parties":[{"t":"La réaction","html":"<div class='def'><b>Définition</b>La réaction de dosage est totale : <strong>B + H₃O⁺ → BH⁺ + H₂O</strong>. À l'équivalence, le pH est <strong>inférieur à 7</strong>.</div>"},{"t":"La courbe","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":24,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une usine de produits ménagers à Douala veut contrôler la concentration d'une solution ammoniacale.","tache":"Présente les grandes étapes du dosage."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-chimie-r25",{"duree":20,"titre":"Les solutions tampons","accroche":"Pourquoi le pH du sang reste presque constant.","intro":"Une solution tampon résiste aux variations de pH. Elle joue un rôle essentiel dans les organismes.","objectifs":["définir une solution tampon","calculer son pH","citer une préparation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>solution tampon</strong> est une solution dont le pH varie peu par addition modérée d'acide, de base, ou par dilution.</div>"},{"t":"Préparation","verrou":true},{"t":"Rôle biologique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"chimie","rang":25,"apc":{"module":"Cinétique et réactions acide-base","famille":"Contrôle de la qualité des produits de la vie courante","agir":"Mesurer, doser et interpréter","situation":"Une biologiste d'un laboratoire de Yaoundé doit maintenir un milieu à pH proche de 4,8 pour une culture.","tache":"Propose une solution adaptée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r01",{"duree":20,"titre":"Le concept de relations internationales","accroche":"Le Cameroun n'est pas seul au monde.","intro":"Aucun État ne vit isolé : il échange des biens, des idées, des personnes et des services avec les autres. Ces échanges forment les relations internationales.","objectifs":["définir les relations internationales","identifier leurs acteurs","distinguer leurs domaines"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>relations internationales</strong> sont l'ensemble des rapports (politiques, économiques, culturels, militaires, humanitaires) qui se nouent entre les États et les autres acteurs au-delà des frontières nationales.</div>"},{"t":"Les acteurs","html":"<ul><li><strong>les États</strong>, acteurs principaux, représentés par leurs chefs d'État, ministres des Relations extérieures et ambassadeurs ;</li><li><strong>les organisations internationales</strong> : ONU, Union africaine, CEMAC ;</li><li><strong>les ONG</strong> : Croix-Rouge, Médecins sans frontières ;</li><li><strong>les entreprises multinationales</strong> ;</li><li><strong>les individus</strong> : diaspora, sportifs, artistes.</li></ul>","retenir":"États, organisations, ONG, entreprises, individus.","labo":{"type":"trier","invite":"Choisis un acteur.","items":[["États","acteurs principaux, représentés par les diplomates."],["Organisations internationales","ONU, Union africaine, CEMAC."],["ONG","Croix-Rouge, Médecins sans frontières."],["Multinationales","entreprises présentes dans plusieurs pays."]]}},{"t":"Les domaines et les instruments","html":"<p>Domaines : politique et diplomatique, économique et commercial, culturel et scientifique, militaire et sécuritaire, humanitaire. Instruments : la <strong>diplomatie</strong> (ambassades, consulats, visites officielles), les <strong>traités</strong> et accords, les <strong>organisations</strong> internationales. Au Cameroun, la politique étrangère est définie par le président de la République et mise en œuvre par le ministère des Relations extérieures.</p><div class='attention'><b>Attention</b>ne pas confondre relations internationales (l'ensemble des rapports) et diplomatie (l'instrument de conduite de ces rapports).</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Les relations internationales sont les rapports qui se nouent :</p><ol type='a'><li>entre les membres d'une même famille et leurs voisins du quartier</li><li>entre les élèves d'un même lycée</li><li>entre les communes d'un même département</li><li>entre États et autres acteurs au-delà des frontières</li></ol><details><summary>Voir la réponse</summary><p><strong>entre États et autres acteurs au-delà des frontières</strong>. Elles dépassent le cadre national.</p></details><p><strong>Vérification des savoir-faire.</strong></p><p>Cite deux acteurs non étatiques des relations internationales.</p><details><summary>Voir la réponse</summary><p>(Réponse : les ONG, comme la Croix-Rouge, et les entreprises multinationales.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Situation-problème.</strong> Document : une ONG internationale finance une clinique à Bertoua ; une multinationale exploite le bois de l'Est ; le Cameroun signe un accord commercial avec le Nigeria.</p><p><strong>Tâche 1.</strong> Identifie l'acteur et le domaine de chaque fait.</p><p><strong>Tâche 2.</strong> Montre la diversité des relations internationales.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>ONG : acteur non étatique, domaine sanitaire et humanitaire ; multinationale : acteur économique ; Cameroun : État, domaine commercial et diplomatique. Les relations internationales mêlent acteurs publics et privés dans des domaines variés.</p></details></div>","retenir":"Savoir-être mobilisé : Ouverture au monde."}],"revision":["Relations internationales : rapports entre États et acteurs au-delà des frontières.","Acteurs : États, organisations, ONG, multinationales, individus.","Instruments : diplomatie, traités, organisations."],"exo":"<p>Cite deux acteurs non étatiques des relations internationales. <em>(Réponse : les ONG, comme la Croix-Rouge, et les entreprises multinationales.)</em></p>","quiz":[{"q":"Les relations internationales sont les rapports qui se nouent :","r":["entre les membres d'une même famille et leurs voisins du quartier","entre les élèves d'un même lycée","entre les communes d'un même département","entre États et autres acteurs au-delà des frontières"],"b":3,"e":"Elles dépassent le cadre national."},{"q":"L'acteur principal des relations internationales est :","r":["l'État","la tontine","le chef de quartier","le syndicat d'enseignants"],"b":0,"e":"Les États restent les acteurs majeurs."},{"q":"Une ONG est :","r":["un organe de l'armée nationale chargé de l'aide","une organisation non gouvernementale","une organisation de l'État","une entreprise publique"],"b":1,"e":"Exemple : la Croix-Rouge."},{"q":"La politique étrangère du Cameroun est définie par :","r":["le maire de Yaoundé, capitale politique","le gouverneur du Centre","le président de la République","le président du Sénat"],"b":2,"e":"Le MINREX la met en œuvre."},{"q":"Le ministère chargé de la diplomatie au Cameroun est :","r":["le ministère de l'Administration territoriale","le ministère du Commerce","le ministère des Sports","le ministère des Relations extérieures"],"b":3,"e":"Le ministère des Relations extérieures (MINREX) met en œuvre la politique étrangère."},{"q":"Un traité est :","r":["un accord écrit entre États","une loi votée par une commune","une décision d'un tribunal local","un discours présidentiel"],"b":0,"e":"Il crée des obligations entre les parties."},{"q":"La diplomatie est :","r":["l'ensemble des relations internationales d'un pays avec les autres","l'instrument de conduite des relations entre États","une organisation régionale","une forme de guerre"],"b":1,"e":"On ne la confond pas avec les relations internationales."},{"q":"Une entreprise multinationale est :","r":["limitée à une seule ville","propriété d'une tontine","présente dans plusieurs pays","un service de l'État"],"b":2,"e":"Elle est un acteur économique international."},{"q":"Un domaine des relations internationales est :","r":["le domaine familial","le domaine scolaire local","le domaine municipal","le domaine humanitaire"],"b":3,"e":"Aide aux victimes de crises."},{"q":"Un footballeur camerounais célèbre à l'étranger est un acteur :","r":["individuel des relations internationales","étatique des relations internationales","judiciaire international","militaire international"],"b":0,"e":"Les individus participent aussi aux échanges."}],"c":"Tle C","m":"ecm","rang":1,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"Un footballeur camerounais évoluant en Europe finance une école dans son village ; la même semaine, le ministre des Relations extérieures signe un accord avec un pays voisin et une ONG distribue des vivres aux déplacés de l'Extrême-Nord.","tache":"Identifie l'acteur et le domaine des relations internationales dans chacun des trois faits."},"gratuit":true});
VRT_L("tle-c-ecm-r02",{"duree":20,"titre":"Les aspects et les formes de la coopération internationale","accroche":"Travailler ensemble pour se développer.","intro":"La coopération internationale est la forme pacifique et organisée des relations entre États. Elle peut associer deux pays ou plusieurs, et concerner de nombreux domaines.","objectifs":["définir la coopération internationale","distinguer coopération bilatérale et multilatérale","citer ses domaines"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>coopération internationale</strong> est l'ensemble des actions concertées par lesquelles des États ou des organisations unissent leurs moyens pour atteindre des objectifs communs : développement, paix, échanges.</div>"},{"t":"Les formes","verrou":true},{"t":"Les aspects (domaines)","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":2,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"En une année, le Cameroun reçoit des bourses d'études d'un pays asiatique, signe avec ses voisins un accord contre le terrorisme dans le cadre d'une organisation régionale, et la commune d'Ebolowa se jumelle avec une ville européenne.","tache":"Pour chaque fait, identifie la forme et le domaine de coopération, puis montre l'intérêt de cette diversité pour le Cameroun."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r03",{"duree":20,"titre":"Dossier : l'assistance humanitaire","accroche":"Secourir les populations en détresse.","intro":"Conflits, catastrophes et épidémies plongent des populations dans la détresse. L'assistance humanitaire leur apporte un secours immédiat. Le Cameroun en reçoit et en donne.","objectifs":["définir l'assistance humanitaire","citer ses principes et ses acteurs","analyser la situation humanitaire au Cameroun"],"parties":[{"t":"Définition et principes","html":"<div class='def'><b>Définition</b>L'<strong>assistance humanitaire</strong> est l'aide matérielle et médicale apportée d'urgence aux victimes de conflits, de catastrophes naturelles ou d'épidémies pour sauver des vies et soulager les souffrances.</div><p>Principes : <strong>humanité</strong>, <strong>neutralité</strong> (ne pas prendre parti), <strong>impartialité</strong> (aider selon les besoins seuls), <strong>indépendance</strong>.</p>"},{"t":"Les acteurs","verrou":true},{"t":"La situation au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":3,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"Après des inondations, 1 200 familles d'un quartier de Maroua sont sans abri ; une ONG ne veut distribuer des vivres qu'aux familles d'une seule religion.","tache":"Explique quel principe humanitaire cette ONG viole et propose trois actions d'assistance d'urgence adaptées."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r04",{"duree":20,"titre":"Les principes de la diplomatie camerounaise","accroche":"Les règles qui guident le Cameroun face au monde.","intro":"Depuis l'indépendance, la diplomatie camerounaise repose sur des principes constants, souvent résumés par le choix de la paix, du dialogue et de l'ouverture.","objectifs":["énoncer les principes de la diplomatie camerounaise","les illustrer par des exemples","identifier les acteurs de la diplomatie"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>diplomatie</strong> est l'art et la pratique de conduire les relations entre États par la négociation. Les <strong>principes de la diplomatie camerounaise</strong> sont les règles fondamentales qui orientent la politique étrangère du pays.</div>"},{"t":"Les principes","verrou":true},{"t":"Les acteurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":4,"apc":{"module":"Les principes de la diplomatie camerounaise","famille":"Le Cameroun dans le monde","agir":"Défendre les intérêts et l'image du Cameroun dans ses relations avec les autres","situation":"Un pays voisin traverse une crise politique ; certains internautes camerounais demandent que le Cameroun « choisisse un camp » et envoie des troupes soutenir l'opposition de ce pays.","tache":"Explique, à l'aide de deux principes de la diplomatie camerounaise, pourquoi le Cameroun ne peut pas agir ainsi, et propose une attitude conforme à ces principes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r05",{"duree":20,"titre":"Le Cameroun et l'Organisation des Nations unies","accroche":"Membre de l'ONU depuis le 20 septembre 1960.","intro":"L'ONU est la grande organisation de la coopération mondiale. Le Cameroun, dont l'indépendance a été préparée sous tutelle de l'ONU, y est admis le 20 septembre 1960.","objectifs":["présenter l'ONU","décrire les relations entre le Cameroun et l'ONU","citer les institutions spécialisées présentes au Cameroun"],"parties":[{"t":"L'ONU","html":"<div class='def'><b>Définition</b>L'<strong>Organisation des Nations unies</strong> (ONU) est une organisation internationale créée le 24 octobre 1945 par la Charte de San Francisco pour maintenir la paix et la sécurité internationales et favoriser la coopération entre les nations.</div><p>Ses organes principaux : l'<strong>Assemblée générale</strong>, le <strong>Conseil de sécurité</strong>, le <strong>Secrétariat</strong>, la <strong>Cour internationale de justice</strong>, le <strong>Conseil économique et social</strong>.</p>"},{"t":"Le Cameroun à l'ONU","verrou":true},{"t":"Les agences de l'ONU au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":5,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Dans ton village de l'Adamaoua, une campagne de vaccination est appuyée par l'OMS et l'UNICEF, et la cantine de l'école reçoit des vivres du PAM ; un habitant affirme que « l'ONU ne sert à rien pour nous ».","tache":"Montre-lui, à l'aide de ces exemples et du cours, trois apports de l'ONU au Cameroun."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r06",{"duree":20,"titre":"Dossier : la participation du Cameroun aux missions des Nations unies","accroche":"Les Casques bleus camerounais.","intro":"Le Cameroun contribue au maintien de la paix en envoyant des militaires et des policiers dans les missions de l'ONU, notamment en République centrafricaine.","objectifs":["définir une opération de maintien de la paix","présenter la participation camerounaise","évaluer ses apports et ses difficultés"],"parties":[{"t":"Les opérations de maintien de la paix","html":"<div class='def'><b>Définition</b>Une <strong>opération de maintien de la paix</strong> est une mission décidée par le Conseil de sécurité de l'ONU, qui déploie des militaires, des policiers et des civils (les Casques bleus) pour protéger les civils et aider un pays à sortir d'un conflit.</div>"},{"t":"La participation camerounaise","verrou":true},{"t":"Apports et difficultés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":6,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un sous-officier de Ngaoundéré, de retour d'une mission en Centrafrique, raconte avoir escorté des convois humanitaires et protégé un camp de déplacés ; son jeune frère se demande « pourquoi risquer sa vie chez les autres ».","tache":"Explique deux intérêts de cette participation pour le Cameroun et deux pour la population centrafricaine."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r07",{"duree":20,"titre":"Le Cameroun et l'Union européenne","accroche":"Un partenaire commercial et financier majeur.","intro":"L'Union européenne est l'un des principaux partenaires commerciaux et financiers du Cameroun. Leur coopération repose sur des accords successifs et sur l'Accord de partenariat économique.","objectifs":["présenter l'Union européenne","décrire les domaines de coopération","analyser l'Accord de partenariat économique"],"parties":[{"t":"L'Union européenne","html":"<div class='def'><b>Définition</b>L'<strong>Union européenne</strong> (UE) est une union politique et économique de pays européens, qui partagent un marché commun et des institutions communes (Commission, Parlement, Conseil).</div><p>Le Cameroun coopère avec elle dans le cadre des accords entre l'UE et les pays d'Afrique, des Caraïbes et du Pacifique : accords de Lomé, puis de <strong>Cotonou</strong> (2000).</p>"},{"t":"Les domaines de coopération","verrou":true},{"t":"L'Accord de partenariat économique (APE)","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":7,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Une coopérative de bananes de la région du Moungo exporte vers l'Europe sans droits de douane, mais une usine de jus de Douala se plaint de la concurrence de jus européens importés à bas prix.","tache":"À partir de ces deux exemples, présente un avantage et un inconvénient de l'APE, puis propose une mesure pour en tirer davantage profit."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r08",{"duree":20,"titre":"Le Cameroun, la Francophonie, le Commonwealth et l'Organisation de la coopération islamique","accroche":"Trois réseaux, une même ouverture.","intro":"Grâce à son héritage bilingue et à la diversité de sa population, le Cameroun appartient à la fois à la Francophonie, au Commonwealth et à l'Organisation de la coopération islamique.","objectifs":["présenter ces trois organisations","expliquer l'appartenance du Cameroun","identifier les avantages pour le pays"],"parties":[{"t":"L'Organisation internationale de la Francophonie","html":"<div class='def'><b>Définition</b>L'<strong>Organisation internationale de la Francophonie</strong> (OIF) regroupe des États et gouvernements ayant le français en partage, pour promouvoir la langue française, la diversité culturelle, la paix, la démocratie et l'éducation.</div><p>Le Cameroun en est membre ; il bénéficie de programmes d'éducation, de formation et d'observation électorale, et accueille des institutions comme l'Agence universitaire de la Francophonie.</p>"},{"t":"Le Commonwealth","verrou":true},{"t":"L'Organisation de la coopération islamique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":8,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Ton camarade affirme qu'appartenir à la fois à la Francophonie et au Commonwealth est « contradictoire » et qu'il faudrait choisir l'une des deux organisations.","tache":"Réfute son affirmation en trois arguments tirés du cours."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r09",{"duree":20,"titre":"Le Cameroun et la France, le Cameroun et la Grande-Bretagne","accroche":"Deux partenaires hérités de l'histoire.","intro":"Anciennes puissances de tutelle, la France et la Grande-Bretagne restent des partenaires importants du Cameroun dans de nombreux domaines, dans le cadre d'une coopération entre États souverains.","objectifs":["présenter l'histoire de ces relations","décrire les domaines de coopération","porter un regard critique sur ces relations"],"parties":[{"t":"L'héritage historique","html":"<div class='def'><b>Définition</b>La <strong>coopération bilatérale</strong> est la relation organisée entre deux États. Avec la France et la Grande-Bretagne, elle prolonge des liens historiques : protectorat allemand jusqu'en 1916, puis partage du territoire entre la France et la Grande-Bretagne sous mandat de la SDN puis sous tutelle de l'ONU.</div>"},{"t":"Le Cameroun et la France","verrou":true},{"t":"Le Cameroun et la Grande-Bretagne","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":9,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un article indique qu'une partie de la dette du Cameroun envers la France a été convertie en financements de routes, d'écoles et de projets agricoles ; un internaute y voit « un cadeau sans contrepartie ».","tache":"Explique le mécanisme du C2D et montre ses avantages et ses limites pour le Cameroun."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r10",{"duree":20,"titre":"Le Cameroun et les pays asiatiques : la Chine, le Japon","accroche":"Des partenaires venus de l'Est.","intro":"Depuis quelques décennies, l'Asie occupe une place croissante dans les relations du Cameroun, notamment la Chine pour les infrastructures et le Japon pour l'aide technique.","objectifs":["décrire la coopération sino-camerounaise","décrire la coopération nippo-camerounaise","évaluer ces partenariats"],"parties":[{"t":"Le Cameroun et la Chine","html":"<div class='def'><b>Définition</b>La <strong>coopération sino-camerounaise</strong> est la relation entre le Cameroun et la République populaire de Chine, avec laquelle il a établi des relations diplomatiques le 26 mars 1971.</div><ul><li>infrastructures : Palais des Congrès et Palais polyvalent des sports de Yaoundé, barrage de Memve'ele, port en eau profonde de Kribi, routes ;</li><li>prêts et dons ;</li><li>bourses, Institut Confucius et coopération médicale ;</li><li>commerce : la Chine est devenue l'un des premiers partenaires commerciaux du Cameroun.</li></ul>"},{"t":"Le Cameroun et le Japon","verrou":true},{"t":"Évaluation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":10,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Sur un chantier routier financé par un prêt étranger à l'Est du Cameroun, un tiers seulement des ouvriers sont camerounais ; les jeunes du village réclament des emplois.","tache":"Analyse deux avantages et deux limites de ce type de coopération et propose deux clauses à exiger dans les futurs accords."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r11",{"duree":20,"titre":"Le Cameroun et les pays d'Amérique : les États-Unis, le Brésil","accroche":"Coopérer avec l'Amérique du Nord et du Sud.","intro":"Les États-Unis sont un partenaire politique, sécuritaire et économique du Cameroun ; le Brésil, grand pays du Sud, est un partenaire de la coopération Sud-Sud.","objectifs":["décrire la coopération avec les États-Unis","décrire la coopération avec le Brésil","comparer ces deux partenariats"],"parties":[{"t":"Le Cameroun et les États-Unis","html":"<div class='def'><b>Définition</b>La <strong>coopération américano-camerounaise</strong> est la relation bilatérale entre le Cameroun et les États-Unis d'Amérique, qui couvre les domaines politique, sécuritaire, commercial, sanitaire et éducatif.</div><ul><li>commerce dans le cadre de l'<strong>AGOA</strong> (loi américaine de 2000 sur la croissance et les opportunités en Afrique), qui ouvre le marché américain à certains produits africains ;</li><li>santé : lutte contre le VIH-sida et le paludisme ;</li><li>éducation : bourses et volontaires du Corps de la paix ;</li><li>sécurité : appui à la lutte contre le terrorisme.</li></ul>"},{"t":"Le Cameroun et le Brésil","verrou":true},{"t":"Comparer les partenariats","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":11,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Une entreprise de Douala qui exporte des vêtements vers les États-Unis grâce à l'AGOA craint de perdre cet avantage ; un groupe d'agriculteurs de l'Ouest souhaite profiter de l'expérience brésilienne sur le café et le soja.","tache":"Explique la nature de chacune des deux coopérations et propose une action pour sécuriser ou développer chacune d'elles."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r12",{"duree":20,"titre":"Dossier : l'aide au développement","accroche":"Une aide utile, à condition d'être bien utilisée.","intro":"Le Cameroun reçoit des aides de ses partenaires pour financer son développement. Ce dossier analyse leurs formes, leurs apports et leurs limites.","objectifs":["définir l'aide au développement","en distinguer les formes","analyser ses effets"],"parties":[{"t":"Définition et formes","html":"<div class='def'><b>Définition</b>L'<strong>aide publique au développement</strong> est l'ensemble des ressources (dons et prêts à conditions favorables) fournies par des États ou des organisations à des pays en développement pour améliorer le bien-être de leur population.</div><ul><li><strong>dons</strong> : sommes non remboursables ;</li><li><strong>prêts concessionnels</strong> : taux faibles, longues durées ;</li><li><strong>aide technique</strong> : experts, formations ;</li><li><strong>aide en nature</strong> : vivres, médicaments, matériel ;</li><li><strong>allègement de la dette</strong>.</li></ul><p>On distingue aussi l'aide <strong>bilatérale</strong> (d'un État à un autre) et <strong>multilatérale</strong> (par une organisation), l'aide <strong>d'urgence ou humanitaire</strong> (catastrophes, réfugiés : HCR, PAM), l'aide <strong>privée</strong> (ONG, fondations), et l'aide <strong>liée</strong> (obligation d'acheter les biens et services du pays donateur) ou <strong>déliée</strong>.</p>"},{"t":"Les bailleurs","verrou":true},{"t":"Apports et limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":12,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un projet d'adduction d'eau de 900 millions de F, financé par un bailleur, a démarré avec deux ans de retard à cause de la lenteur des fonds de contrepartie nationaux et d'une passation de marché contestée ; le village attend toujours l'eau potable.","tache":"Analyse deux causes et deux conséquences de ce retard, puis propose deux mesures pour améliorer l'efficacité de l'aide."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r13",{"duree":20,"titre":"Le Cameroun et l'Union africaine","accroche":"Membre fondateur de l'unité africaine.","intro":"Membre fondateur de l'Organisation de l'unité africaine en 1963, le Cameroun participe à l'Union africaine qui lui a succédé en 2002.","objectifs":["présenter l'OUA et l'UA","citer les organes de l'UA","décrire la contribution du Cameroun"],"parties":[{"t":"De l'OUA à l'UA","html":"<div class='def'><b>Définition</b>L'<strong>Union africaine</strong> (UA) est l'organisation panafricaine qui regroupe les États africains pour promouvoir l'unité, la paix, la sécurité et le développement du continent. Elle a été lancée à Durban le 9 juillet 2002 et a son siège à Addis-Abeba.</div><p>Elle a succédé à l'<strong>Organisation de l'unité africaine</strong> (OUA), créée le 25 mai 1963 à Addis-Abeba, dont le Cameroun était membre fondateur (Ahmadou Ahidjo). La <strong>déclaration de Syrte</strong> (9 septembre 1999) prépare la transformation ; l'<strong>Acte constitutif</strong> de l'UA est adopté à Lomé en 2000. L'UA compte 55 États membres.</p>"},{"t":"Les organes et les objectifs","verrou":true},{"t":"La contribution du Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":13,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"La zone de libre-échange continentale africaine doit permettre à une entreprise de jus de fruits de Bafoussam de vendre au Kenya ou au Sénégal avec des droits de douane réduits ; son directeur hésite à investir.","tache":"Présente deux objectifs de l'UA liés à ce projet et deux conditions pour que l'entreprise en profite."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r14",{"duree":20,"titre":"Le Cameroun dans sa sous-région","accroche":"Le Cameroun, carrefour de l'Afrique centrale.","intro":"Par sa position, sa population et son économie, le Cameroun joue un rôle central en Afrique centrale. Il appartient à plusieurs organisations sous-régionales.","objectifs":["citer les organisations sous-régionales du Cameroun","décrire leurs objectifs","évaluer la place du Cameroun et les obstacles à l'intégration"],"parties":[{"t":"Les organisations","html":"<div class='def'><b>Définition</b>L'<strong>intégration sous-régionale</strong> est le processus par lequel des États voisins mettent en commun des politiques et des institutions pour former un espace économique et politique plus uni.</div><ul><li>la <strong>CEMAC</strong> (Communauté économique et monétaire de l'Afrique centrale), créée en 1994, siège à Bangui : Cameroun, Centrafrique, Congo, Gabon, Guinée équatoriale, Tchad ; monnaie commune (franc CFA) gérée par la <strong>BEAC</strong>, dont le siège est à Yaoundé ; la <strong>COBAC</strong> (Commission bancaire de l'Afrique centrale) veille au respect de la réglementation par les banques et sanctionne les manquements ; les États ont harmonisé leur réglementation bancaire par la convention du 17 janvier 1992 ;</li><li>la <strong>CEEAC</strong> (Communauté économique des États de l'Afrique centrale), créée en 1983 ;</li><li>la <strong>Commission du bassin du lac Tchad</strong> ;</li><li>la <strong>Commission du golfe de Guinée</strong>.</li></ul>"},{"t":"La place du Cameroun","verrou":true},{"t":"Les obstacles à l'intégration","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":14,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Une commerçante de Kye-Ossi, à la frontière du Gabon et de la Guinée équatoriale, se plaint de contrôles multiples et de paiements non officiels qui allongent son trajet de vingt-quatre heures.","tache":"Identifie l'obstacle à l'intégration illustré par ce cas et propose trois solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r15",{"duree":20,"titre":"Dossier : le COPAX, Conseil de paix et de sécurité de l'Afrique centrale","accroche":"Prévenir et gérer les conflits entre voisins.","intro":"Pour faire face aux crises de la sous-région, les États de la CEEAC ont créé le Conseil de paix et de sécurité de l'Afrique centrale (COPAX), dont le protocole a été signé à Malabo le 24 février 2000.","objectifs":["présenter le COPAX","décrire ses organes","évaluer son action"],"parties":[{"t":"Présentation","html":"<div class='def'><b>Définition</b>Le <strong>COPAX</strong> est le mécanisme de la CEEAC chargé de la promotion, du maintien et de la consolidation de la paix et de la sécurité en Afrique centrale.</div><p>Il a été créé au sommet des chefs d'État de la CEEAC tenu à <strong>Yaoundé</strong> le 25 février 1999 ; son protocole a été signé à <strong>Malabo</strong> le 24 février 2000 et ratifié par le Cameroun le 28 avril 2000.</p>"},{"t":"Les organes techniques","verrou":true},{"t":"Action et limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":15,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Des pirates attaquent des chalutiers au large du golfe de Guinée ; les pêcheurs de Limbé et d'Idenau ne sortent plus en mer et le prix du poisson augmente au marché.","tache":"Montre en quoi le COPAX peut contribuer à résoudre ce problème et propose deux mesures sous-régionales."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r16",{"duree":20,"titre":"TD : la contribution du Cameroun dans la gestion des conflits en Afrique","accroche":"Médiateur, soldat de la paix, terre d'accueil.","intro":"Ce travail dirigé recense et analyse les actions du Cameroun pour prévenir et gérer les conflits en Afrique, en s'appuyant sur des exemples concrets.","objectifs":["recenser les formes de contribution","analyser des exemples","rédiger une synthèse argumentée"],"parties":[{"t":"Les formes de contribution","html":"<div class='def'><b>Définition</b>La <strong>gestion des conflits</strong> est l'ensemble des actions destinées à prévenir une crise, à y mettre fin et à reconstruire la paix.</div><ul><li>le <strong>règlement pacifique</strong> de ses propres différends (Bakassi) ;</li><li>l'envoi de <strong>contingents</strong> dans les missions de paix (MINUSCA) ;</li><li>la <strong>lutte commune</strong> contre Boko Haram au sein de la Force multinationale mixte ;</li><li>l'<strong>accueil des réfugiés</strong> centrafricains et nigérians ;</li><li>la <strong>formation</strong> des personnels de paix à l'EIFORCES ;</li><li>la participation au COPAX et au Conseil de paix et de sécurité de l'UA.</li></ul>"},{"t":"Analyser un exemple","verrou":true},{"t":"Rédiger la synthèse","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":16,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Ton professeur te demande de préparer, pour l'exposé de la semaine prochaine, une fiche sur « le Cameroun, acteur de paix en Afrique » ; tu disposes d'une heure et de trois exemples : Bakassi, la MINUSCA et le camp de Minawao.","tache":"Propose un plan détaillé de l'exposé et rédige l'introduction en cinq lignes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-ecm-r17",{"duree":20,"titre":"Dossier : les problèmes du Cameroun dans les relations internationales","accroche":"Les défis d'un pays ouvert sur le monde.","intro":"Malgré ses atouts, le Cameroun rencontre des difficultés économiques, politiques et sécuritaires dans ses relations avec le reste du monde. Ce dossier les analyse, comme le demandent les sujets du baccalauréat.","objectifs":["identifier les problèmes du Cameroun dans les relations internationales","en expliquer les causes et les conséquences","proposer des solutions"],"parties":[{"t":"Les problèmes économiques","html":"<div class='def'><b>Définition</b>Un <strong>problème du Cameroun dans les relations internationales</strong> est une difficulté qui limite sa capacité à défendre ses intérêts ou à tirer profit de ses échanges avec les autres.</div><ul><li><strong>la dépendance aux matières premières</strong> (pétrole, cacao, bois) dont les prix varient ;</li><li><strong>l'endettement</strong> extérieur ;</li><li><strong>le déséquilibre de la balance commerciale</strong> : importations supérieures aux exportations ;</li><li><strong>la faible transformation locale</strong> des produits ;</li><li><strong>les conditions imposées</strong> par certains bailleurs.</li></ul>"},{"t":"Les problèmes politiques et sécuritaires","verrou":true},{"t":"Des solutions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"ecm","rang":17,"apc":{"module":"Le Cameroun dans la coopération multilatérale","famille":"Le Cameroun dans le monde","agir":"Promouvoir une coopération bénéfique au développement et à la paix","situation":"Un tableau indique que le Cameroun exporte surtout du pétrole brut, du cacao en fèves et du bois, et importe des produits manufacturés, du riz et du poisson congelé ; lorsque le cours du cacao baisse, les revenus des planteurs du Centre et du Sud-Ouest chutent.","tache":"Analyse deux problèmes économiques révélés par ce tableau (causes et conséquences) et propose deux solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r07",{"duree":20,"titre":"Écriture algébrique et calculs dans ℂ","accroche":"Un nombre dont le carré vaut −1 ouvre un monde nouveau.","intro":"Dans ℝ, l'équation x² = −1 n'a pas de solution. Les nombres complexes sont nés pour la résoudre.","objectifs":["écrire un complexe sous forme algébrique","additionner et multiplier","calculer un quotient"],"parties":[{"t":"L'ensemble ℂ","html":"<div class='def'><b>Définition</b>Un <strong>nombre complexe</strong> s'écrit de façon unique <strong>z = a + ib</strong>, avec a et b réels et i² = −1. a est la partie réelle, b la partie imaginaire.</div>"},{"t":"Les calculs","verrou":true},{"t":"Le quotient","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":7,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un ingénieur stagiaire à la centrale de Song Loulou note une impédance sous la forme 3 + 4i et doit la multiplier par 1 − i pour un calcul de circuit.","tache":"Effectue le produit sous forme algébrique."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r08",{"duree":15,"titre":"Les nombres complexes conjugués","accroche":"Un simple changement de signe, et le produit devient réel.","intro":"Le conjugué d'un complexe est un outil de calcul, notamment pour les quotients.","objectifs":["calculer un conjugué","utiliser ses propriétés","reconnaître un réel ou un imaginaire pur"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>conjugué</strong> de z = a + ib est <strong>z̄ = a − ib</strong>.</div>"},{"t":"Propriétés","verrou":true},{"t":"Caractériser un complexe","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":8,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un technicien en formation dans un poste électrique de Bafoussam obtient l'impédance Z = (3 + 4i)/(1 − 2i) + (3 − 4i)/(1 + 2i) et affirme que le résultat est réel.","tache":"Dis quel critère utiliser avec le conjugué et vérifie son affirmation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r09",{"duree":15,"titre":"Le module d'un nombre complexe","accroche":"La longueur cachée derrière un nombre complexe.","intro":"Le module mesure la distance d'un point à l'origine. Il joue le rôle de la valeur absolue dans ℂ.","objectifs":["calculer un module","utiliser ses propriétés","interpréter géométriquement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>module</strong> de z = a + ib est <strong>|z| = √(a² + b²)</strong>.</div><div class='ex'><b>Exemple</b>|3 + 4i| = 5.</div>"},{"t":"Propriétés","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":9,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur le plan d'un quartier de Douala, une antenne est au point d'affixe 2 + i et un client à 5 + 5i, en kilomètres.","tache":"Calcule la distance entre l'antenne et le client."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r10",{"duree":25,"titre":"Équations de degré 2 et 3 dans ℂ","accroche":"Dans ℂ, toute équation du second degré a des solutions.","intro":"Le discriminant négatif n'est plus un obstacle : les racines deviennent complexes.","objectifs":["résoudre une équation de degré 2","factoriser une équation de degré 3","vérifier ses solutions"],"parties":[{"t":"Degré 2","html":"<div class='def'><b>Théorème</b>L'équation az² + bz + c = 0, à coefficients réels et Δ = b² − 4ac < 0, admet deux solutions conjuguées : <strong>z = (−b ± i√|Δ|) / 2a</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Degré 3","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":10,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour un logo à trois branches identiques, une graphiste de Mbouda place trois points sur un cercle de rayon 1, aux images des solutions de z³ = 1.","tache":"Résous z³ − 1 = 0 et donne la nature du triangle obtenu."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r11",{"duree":20,"titre":"Limites des fonctions trigonométriques et irrationnelles","accroche":"Quand x approche 0, sin x ressemble à x.","intro":"Les formes indéterminées se résolvent avec des limites de référence ou l'expression conjuguée.","objectifs":["utiliser les limites de référence","lever une indétermination","utiliser l'expression conjuguée"],"parties":[{"t":"Limites de référence","html":"<div class='def'><b>Limites à connaître</b>En 0 : <strong>sin x / x → 1</strong>, <strong>(1 − cos x) / x² → 1/2</strong>, <strong>tan x / x → 1</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Fonctions irrationnelles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":11,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour vérifier un calcul d'angle très petit sur un chantier à Limbé, un technicien remplace sin x par x.","tache":"Justifie cette approximation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r12",{"duree":20,"titre":"Fonction continue sur un intervalle","accroche":"Une courbe qu'on trace sans lever le crayon garantit une solution.","intro":"Le théorème des valeurs intermédiaires assure l'existence de solutions sans même les calculer.","objectifs":["définir la continuité","appliquer le théorème des valeurs intermédiaires","encadrer une solution"],"parties":[{"t":"Continuité","html":"<div class='def'><b>Définition</b>f est <strong>continue en a</strong> si lim (x→a) f(x) = f(a). Elle est continue sur un intervalle si elle l'est en tout point.</div>"},{"t":"Théorème des valeurs intermédiaires","verrou":true},{"t":"Dichotomie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":12,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un technicien cherche à quel instant la température d'une chambre froide, à Douala, atteint exactement 4 °C entre deux relevés.","tache":"Dis pourquoi on est sûr qu'un tel instant existe, si la température varie de façon continue."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r13",{"duree":20,"titre":"Fonction continue et strictement monotone","accroche":"Avec la monotonie, la solution devient unique.","intro":"La continuité donne l'existence ; la stricte monotonie donne l'unicité.","objectifs":["énoncer le théorème de la bijection","prouver l'unicité","donner l'intervalle image"],"parties":[{"t":"Le théorème","html":"<div class='def'><b>Théorème</b>Si f est <strong>continue et strictement monotone</strong> sur un intervalle I, alors f réalise une <strong>bijection</strong> de I sur J = f(I).</div>"},{"t":"Conséquence","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":13,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur le marché du cacao de Kumba, l'offre vaut f(p) = p³ + p − 10 (en tonnes) selon le prix p (en milliers de F/kg) ; l'équilibre est atteint quand f(p) = 0, pour p entre 1 et 3.","tache":"Montre que ce prix d'équilibre existe et est unique, puis encadre-le à 0,1 près."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r14",{"duree":25,"titre":"Dérivabilité de la réciproque et accroissements finis","accroche":"Encadrer une différence sans la calculer.","intro":"Deux résultats puissants : la dérivée d'une fonction réciproque, et un encadrement fondé sur la dérivée.","objectifs":["dériver une réciproque","énoncer les inégalités des accroissements finis","appliquer à un encadrement"],"parties":[{"t":"La réciproque","html":"<div class='def'><b>Formule</b>Si f est bijective, dérivable et si f'(f⁻¹(y)) ≠ 0, alors <strong>(f⁻¹)'(y) = 1 / f'(f⁻¹(y))</strong>.</div>"},{"t":"Accroissements finis","verrou":true},{"t":"Application","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":14,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sans calculatrice, un candidat doit encadrer √101 lors d'une épreuve pratique.","tache":"Utilise l'inégalité des accroissements finis."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r15",{"duree":25,"titre":"Représentations graphiques des fonctions","accroche":"Une courbe entière se devine à partir de quelques détails.","intro":"Dérivée, limites, asymptotes et symétries permettent de construire une courbe avec précision.","objectifs":["étudier une fonction","trouver des asymptotes","exploiter une symétrie"],"parties":[{"t":"Plan d'étude","html":"<div class='def'><b>Méthode</b>L'<strong>étude d'une fonction</strong> comporte : domaine, limites, dérivée, tableau de variation, asymptotes, points remarquables, tracé.</div>"},{"t":"Asymptotes","verrou":true},{"t":"Symétries","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":15,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un lycéen de Bertoua doit représenter le coût moyen d'une production, modélisé par x + 1/x, afin de trouver son minimum.","tache":"Dis pour quelle valeur positive le coût est minimal."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r19",{"duree":20,"titre":"Tableaux d'effectifs et nuage de points","accroche":"Deux séries, un nuage de points, une tendance.","intro":"Pour relier deux caractères, on place les données dans un repère et on observe leur forme.","objectifs":["construire un nuage de points","calculer le point moyen","lire un tableau à double entrée"],"parties":[{"t":"Le nuage de points","html":"<div class='def'><b>Définition</b>Pour une série double (xᵢ ; yᵢ), le <strong>nuage de points</strong> est l'ensemble des points Mᵢ(xᵢ ; yᵢ).</div>"},{"t":"Le point moyen","verrou":true},{"t":"Tableau à double entrée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":19,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une coopérative de Foumban note, sur 5 mois, l'engrais utilisé et la récolte de café obtenue.","tache":"Calcule le point moyen pour x : 1, 2, 3, 4, 5 et y : 2, 3, 5, 6, 9."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r20",{"duree":25,"titre":"Ajustements linéaires","accroche":"Trouver la droite qui résume des données pour prévoir l'avenir.","intro":"Une droite d'ajustement permet de faire une prévision à partir d'une tendance observée.","objectifs":["calculer covariance et coefficient","écrire la droite de régression","faire une prévision"],"parties":[{"t":"La droite des moindres carrés","html":"<div class='def'><b>Formules</b>La <strong>droite de régression</strong> de y en x passe par G : <strong>y − ȳ = a(x − x̄)</strong>, avec <strong>a = cov(x ; y) / V(x)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Corrélation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":20,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La même coopérative veut prévoir la récolte si elle consacre 6 unités d'engrais.","tache":"Calcule l'estimation avec y = 1,7x − 0,1."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r24",{"duree":20,"titre":"Le raisonnement par récurrence","accroche":"Comme une rangée de dominos : le premier tombe, tous tombent.","intro":"Pour prouver une propriété valable pour tout entier, il suffit de deux étapes.","objectifs":["rédiger une récurrence","prouver une formule","éviter les erreurs de rédaction"],"parties":[{"t":"Le principe","html":"<div class='def'><b>Principe</b>Pour démontrer P(n) pour tout n ≥ n₀ : <strong>initialisation</strong>, P(n₀) est vraie ; <strong>hérédité</strong>, si P(n) est vraie, alors P(n + 1) l'est aussi.</div>"},{"t":"Exemple","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":24,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour la cérémonie de fin d'année à Yaoundé, on dispose des chaises : 1 au premier rang, 2 au deuxième, et ainsi de suite.","tache":"Exprime le nombre total pour n rangs et justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r25",{"duree":20,"titre":"Suites monotones et suites bornées","accroche":"Une suite qui monte sans dépasser un plafond finit par se stabiliser.","intro":"Connaître le sens de variation et les bornes d'une suite renseigne sur son comportement.","objectifs":["étudier le sens de variation","majorer ou minorer","utiliser le théorème de convergence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Une suite est <strong>croissante</strong> si uₙ₊₁ ≥ uₙ pour tout n. Elle est <strong>majorée</strong> par M si uₙ ≤ M pour tout n.</div>"},{"t":"Étudier le sens","verrou":true},{"t":"Le théorème","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":25,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"L'épargne d'une tontine de Bafia augmente chaque mois, mais la caisse est plafonnée.","tache":"Dis ce que l'on peut déduire si le montant mensuel forme une suite croissante et majorée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r26",{"duree":25,"titre":"Convergence de suites définies par récurrence","accroche":"uₙ₊₁ = f(uₙ) : où va la suite ?","intro":"Une suite auxiliaire géométrique permet souvent de calculer directement la limite.","objectifs":["trouver un point fixe","introduire une suite auxiliaire","calculer une limite"],"parties":[{"t":"Le point fixe","html":"<div class='def'><b>Propriété</b>Si uₙ₊₁ = f(uₙ) converge vers L et si f est continue en L, alors <strong>L = f(L)</strong>.</div>"},{"t":"La suite auxiliaire","verrou":true},{"t":"La limite","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":26,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un réservoir à Maroua, on retire la moitié de l'eau chaque jour, puis on ajoute 1 000 L.","tache":"Dis vers quel volume se stabilise le réservoir."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r28",{"duree":15,"titre":"Graphes : le vocabulaire","accroche":"Des villes et des routes deviennent des points et des traits.","intro":"Les graphes modélisent des réseaux de routes, de téléphone ou d'amis.","objectifs":["définir sommet et arête","calculer un degré","lire une matrice d'adjacence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Un <strong>graphe</strong> est un ensemble de <strong>sommets</strong> reliés par des <strong>arêtes</strong>. Le <strong>degré</strong> d'un sommet est le nombre d'arêtes qui en partent.</div>"},{"t":"Propriété","verrou":true},{"t":"La matrice d'adjacence","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":28,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une société de transport relie Douala, Yaoundé, Bafoussam et Kribi selon quatre liaisons directes.","tache":"Représente ce réseau et calcule la somme des degrés."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r29",{"duree":25,"titre":"Graphes : propriétés et algorithmes","accroche":"Trouver le plus court chemin entre deux villes.","intro":"Euler, en se promenant, a posé les bases de la théorie des graphes. Dijkstra a formalisé la recherche du plus court chemin.","objectifs":["appliquer le théorème d'Euler","utiliser l'algorithme de Dijkstra","interpréter un résultat"],"parties":[{"t":"Le théorème d'Euler","html":"<div class='def'><b>Théorème</b>Un graphe connexe admet une <strong>chaîne eulérienne</strong> s'il a 0 ou 2 sommets de degré impair. Il admet un <strong>cycle eulérien</strong> s'il en a 0.</div>"},{"t":"Le plus court chemin","verrou":true},{"t":"Lire le résultat","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":29,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un livreur à Yaoundé doit emprunter toutes les rues d'un quartier une seule fois.","tache":"Dis quelle condition sur les degrés rend cela possible."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r30",{"duree":15,"titre":"Image et affixe d'un nombre complexe","accroche":"Chaque complexe a son adresse dans le plan.","intro":"Les nombres complexes se lisent dans le plan : ils relient calcul et géométrie.","objectifs":["placer l'image d'un complexe","calculer l'affixe d'un vecteur","calculer l'affixe d'un milieu"],"parties":[{"t":"Image et affixe","html":"<div class='def'><b>Définition</b>Dans un repère orthonormé, le point M(a ; b) est l'<strong>image</strong> de z = a + ib, et z est l'<strong>affixe</strong> de M.</div>"},{"t":"Vecteurs","verrou":true},{"t":"Milieu et barycentre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":30,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur le plan d'un champ de Foumban, on repère deux bornes par des affixes pour placer un puits à mi-distance.","tache":"Donne l'affixe du puits, si les bornes sont 1 + i et 3 − i."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r31",{"duree":25,"titre":"Forme trigonométrique et notation exponentielle","accroche":"Avec eⁱᶿ, multiplier revient à tourner.","intro":"La forme exponentielle rend les produits et les puissances très simples.","objectifs":["calculer un argument","écrire la forme exponentielle","appliquer la formule de Moivre"],"parties":[{"t":"Forme trigonométrique","html":"<div class='def'><b>Définition</b>Tout complexe non nul s'écrit <strong>z = r(cos θ + i sin θ) = r eⁱᶿ</strong>, où r = |z| et θ est un argument de z.</div><div class='ex'><b>Exemple</b>1 + i = √2 e^(iπ/4).</div>"},{"t":"Règles de calcul","verrou":true},{"t":"Formule de Moivre","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":31,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour étudier la rotation d'une pale d'un moulin à vent expérimental à Maroua, on utilise la forme exponentielle.","tache":"Écris 1 + i sous forme exponentielle."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r32",{"duree":25,"titre":"Linéarisation et racines n-ièmes","accroche":"Les racines d'un complexe dessinent un polygone régulier.","intro":"Les formules d'Euler transforment des puissances de sinus et cosinus en sommes, plus faciles à intégrer.","objectifs":["utiliser les formules d'Euler","linéariser","calculer des racines n-ièmes"],"parties":[{"t":"Formules d'Euler","html":"<div class='def'><b>Formules</b><strong>cos θ = (eⁱᶿ + e⁻ⁱᶿ) / 2</strong> et <strong>sin θ = (eⁱᶿ − e⁻ⁱᶿ) / 2i</strong>.</div>"},{"t":"Linéariser","verrou":true},{"t":"Racines n-ièmes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":32,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une décoration en étoile doit placer 6 points réguliers sur un cercle pour un logo de l'association du lycée à Dschang.","tache":"Explique quelle équation donne ces points."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r33",{"duree":25,"titre":"Complexes et géométrie","accroche":"Un quotient d'affixes dit tout d'un triangle.","intro":"Le calcul complexe démontre l'alignement, le parallélisme et la nature d'un triangle.","objectifs":["interpréter un quotient d'affixes","déterminer la nature d'un triangle","prouver un alignement"],"parties":[{"t":"Le quotient","html":"<div class='def'><b>Propriété</b>Soit Z = (z_C − z_A) / (z_B − z_A). Alors <strong>|Z| = AC / AB</strong> et <strong>arg Z = (vecteur AB ; vecteur AC)</strong>.</div>"},{"t":"Conséquences","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":33,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un géomètre de Kribi veut vérifier qu'un terrain forme un angle droit en A, à partir des affixes de trois bornes.","tache":"Dis quel calcul effectuer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r36",{"duree":15,"titre":"Primitives d'une fonction continue","accroche":"Remonter de la vitesse à la distance.","intro":"Une primitive est une opération inverse de la dérivation.","objectifs":["définir une primitive","vérifier une primitive","trouver une primitive avec condition"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>F est une <strong>primitive</strong> de f sur I si <strong>F' = f</strong> sur I. Toute fonction continue sur un intervalle admet des primitives.</div>"},{"t":"Toutes les primitives","verrou":true},{"t":"Avec une condition","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":36,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La vitesse d'un car sur la route Douala-Édéa est modélisée par v(t) = 2t + 3 (unités du problème).","tache":"Donne la position, sachant qu'elle est nulle à t = 1."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r37",{"duree":20,"titre":"Déterminer des primitives","accroche":"Reconnaître une forme, c'est déjà avoir la primitive.","intro":"Le tableau des primitives usuelles et quelques formes composées suffisent dans la plupart des cas.","objectifs":["utiliser le tableau usuel","reconnaître u'uⁿ","reconnaître u'/u²"],"parties":[{"t":"Primitives usuelles","html":"<div class='def'><b>Tableau</b>xⁿ → xⁿ⁺¹/(n + 1) ; 1/x² → −1/x ; 1/√x → 2√x ; cos x → sin x ; sin x → −cos x.</div>"},{"t":"Formes composées","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":37,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Le débit d'une pompe de Garoua est d(t) = 2t(t² + 1)³, en litres par minute ; on cherche le volume pompé V(t), primitive de d avec V(0) = 0.","tache":"Identifie u, donne une primitive de d et calcule V(1)."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r38",{"duree":25,"titre":"Le logarithme népérien","accroche":"Transformer les produits en sommes.","intro":"Le logarithme népérien répond à une question : quelle est la primitive de 1/x ?","objectifs":["définir ln","utiliser ses propriétés","dériver ln u"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La fonction <strong>logarithme népérien</strong>, notée ln, est la primitive de 1/x sur ]0 ; +∞[ qui s'annule en 1.</div>"},{"t":"Propriétés","verrou":true},{"t":"Limites et dérivée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":38,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une micro-finance de Bafoussam place 100 000 F à intérêts composés. On veut savoir en combien de temps le capital double.","tache":"Écris l'équation à résoudre avec un taux annuel de 10 %."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r39",{"duree":20,"titre":"Autres fonctions logarithmes","accroche":"Du pH à la magnitude : le logarithme décimal partout.","intro":"Le logarithme décimal permet de manipuler des nombres de tailles très différentes.","objectifs":["définir log de base a","calculer un logarithme décimal","résoudre une équation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Pour a > 0 et a ≠ 1, le <strong>logarithme de base a</strong> est <strong>log_a x = ln x / ln a</strong>. Le logarithme décimal est celui de base 10.</div>"},{"t":"Propriétés","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":39,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un technicien de laboratoire à Yaoundé mesure [H₃O⁺] = 10⁻⁴ mol/L dans une eau de source.","tache":"Calcule le pH."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r40",{"duree":15,"titre":"Le vocabulaire des probabilités","accroche":"Avant de calculer une chance, il faut nommer ce que l'on regarde.","intro":"Un vocabulaire précis évite les erreurs de raisonnement.","objectifs":["définir univers et événement","utiliser ∩, ∪ et contraire","reconnaître des événements incompatibles"],"parties":[{"t":"Vocabulaire","html":"<div class='def'><b>Définitions</b>L'<strong>univers</strong> Ω est l'ensemble des issues d'une expérience aléatoire. Un <strong>événement</strong> est une partie de Ω.</div>"},{"t":"Opérations","verrou":true},{"t":"Incompatibles","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":40,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Au tirage d'une tombola de fin d'année au lycée de Sangmélima, on s'intéresse à un ticket pair ou supérieur à 50.","tache":"Écris l'événement avec les symboles."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r41",{"duree":25,"titre":"Calculer la probabilité d'un événement","accroche":"Compter les cas favorables, sans en oublier ni en compter deux fois.","intro":"Dans une situation d'équiprobabilité, une probabilité est un rapport de deux dénombrements.","objectifs":["calculer en équiprobabilité","utiliser les combinaisons","utiliser les formules"],"parties":[{"t":"Équiprobabilité","html":"<div class='def'><b>Formule</b>En cas d'<strong>équiprobabilité</strong>, <strong>P(A) = card A / card Ω</strong>.</div>"},{"t":"Formules","verrou":true},{"t":"Combinaisons","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":41,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un comité de 5 élèves dont 3 filles, à Kumba, on tire 2 délégués au hasard.","tache":"Calcule la probabilité que les 2 délégués soient des filles."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r42",{"duree":25,"titre":"Probabilités conditionnelles","accroche":"Une information nouvelle change la probabilité.","intro":"Sachant qu'un événement s'est produit, on recalcule les chances des autres. C'est le cœur de nombreux problèmes de bac.","objectifs":["calculer une probabilité conditionnelle","construire un arbre","appliquer la formule des probabilités totales"],"parties":[{"t":"Définition","html":"<div class='def'><b>Formule</b>Si P(A) ≠ 0, <strong>P_A(B) = P(A ∩ B) / P(A)</strong>. A et B sont <strong>indépendants</strong> si P(A ∩ B) = P(A) P(B).</div>"},{"t":"Probabilités totales","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":42,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un lycée de Douala, 60 % des candidats au bac sont des filles. 70 % d'entre elles réussissent, contre 50 % des garçons.","tache":"Calcule le taux global de réussite."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r43",{"duree":20,"titre":"Variables aléatoires","accroche":"Un jeu est-il équitable ? L'espérance répond.","intro":"Une variable aléatoire associe un nombre à chaque issue, comme un gain à un jeu.","objectifs":["établir une loi de probabilité","calculer l'espérance","calculer variance et écart-type"],"parties":[{"t":"Loi de probabilité","html":"<div class='def'><b>Définition</b>Une <strong>variable aléatoire</strong> X associe un réel à chaque issue. Sa <strong>loi</strong> donne P(X = xᵢ) pour chaque valeur.</div>"},{"t":"Espérance","verrou":true},{"t":"Variance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":43,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un ticket de loterie du comité des fêtes de Bafang coûte 100 F. Les gains sont 0, 100 ou 500 F avec probabilités 0,7 ; 0,2 ; 0,1.","tache":"Dis si le jeu est favorable au joueur."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r44",{"duree":25,"titre":"Épreuves de Bernoulli et loi binomiale","accroche":"Répéter une expérience à deux issues suit une loi très précise.","intro":"Combien de chances d'obtenir 2 succès en 5 essais ? La loi binomiale le dit.","objectifs":["reconnaître un schéma de Bernoulli","appliquer la loi binomiale","calculer E et V"],"parties":[{"t":"Le schéma de Bernoulli","html":"<div class='def'><b>Définition</b>Une <strong>épreuve de Bernoulli</strong> a deux issues, succès (p) et échec (1 − p). Répétée n fois de manière indépendante, le nombre X de succès suit la <strong>loi binomiale B(n ; p)</strong>.</div>"},{"t":"La formule","verrou":true},{"t":"Espérance et variance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":44,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Dans un lot de semences à Dschang, chaque graine germe avec une probabilité de 0,8. Un paysan en sème 5.","tache":"Calcule la probabilité qu'aucune ne germe."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r34",{"duree":20,"titre":"Similitudes directes : expressions complexes","accroche":"Agrandir et tourner avec une seule formule.","intro":"Une similitude directe combine rotation et homothétie. Elle s'exprime très simplement avec les complexes.","objectifs":["reconnaître l'écriture z' = az + b","trouver l'expression analytique","calculer une image"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>similitude directe</strong> est une transformation du plan d'écriture complexe <strong>z' = az + b</strong>, avec a ≠ 0.</div>"},{"t":"Expression analytique","verrou":true},{"t":"Déterminer une similitude","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":34,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Sur une maquette d'architecte à Yaoundé, un motif est tourné et agrandi avant impression.","tache":"Calcule l'image du point d'affixe 1 + i par z' = 2z + i."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r35",{"duree":25,"titre":"Propriétés des similitudes directes","accroche":"Centre, rapport, angle : la carte d'identité d'une similitude.","intro":"Toute similitude directe qui n'est pas une translation possède un centre, un rapport et un angle.","objectifs":["trouver centre, rapport et angle","utiliser les propriétés","décomposer une similitude"],"parties":[{"t":"Éléments caractéristiques","html":"<div class='def'><b>Propriété</b>Pour z' = az + b, avec a ≠ 1 : <strong>rapport k = |a|</strong>, <strong>angle θ = arg a</strong>, <strong>centre ω = b / (1 − a)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Propriétés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":35,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un motif de pagne fabriqué à Garoua est reproduit par une similitude de rapport 2.","tache":"Dis comment l'aire du motif est modifiée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r45",{"duree":25,"titre":"La fonction exponentielle népérienne","accroche":"La seule fonction égale à sa propre dérivée.","intro":"La fonction exponentielle décrit les croissances rapides : intérêts, populations, épidémies.","objectifs":["définir exp","utiliser ses propriétés","connaître ses limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La fonction <strong>exponentielle</strong> est la réciproque de ln. Elle est définie sur ℝ, à valeurs strictement positives, et vérifie <strong>exp' = exp</strong> et exp(0) = 1.</div>"},{"t":"Propriétés","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":45,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Le nombre de bactéries d'une culture, au laboratoire d'un hôpital de Douala, est modélisé par N(t) = 100 e^(0,5t).","tache":"Calcule au bout de combien de temps le nombre double."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r46",{"duree":25,"titre":"Étude de fonctions définies à l'aide de l'exponentielle","accroche":"Un maximum caché derrière x e⁻ˣ.","intro":"Les fonctions du type u(x)e^v(x) reviennent régulièrement dans les problèmes de bac.","objectifs":["dériver e^u","étudier un produit","tracer la courbe"],"parties":[{"t":"Dérivée","html":"<div class='def'><b>Formule</b>Si u est dérivable, <strong>(e^u)' = u' e^u</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":46,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La concentration d'un médicament dans le sang est modélisée par C(t) = t e⁻ᵗ (unités du problème).","tache":"Détermine à quel moment la concentration est maximale."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r53",{"duree":20,"titre":"L'intégrale : définition et propriétés","accroche":"Additionner une infinité de tranches très fines.","intro":"L'intégrale relie deux idées : aire sous une courbe et primitive.","objectifs":["définir l'intégrale","utiliser la linéarité","utiliser la relation de Chasles"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Si F est une primitive de f sur [a ; b], <strong>∫ₐᵇ f(x) dx = F(b) − F(a)</strong>.</div><div class='ex'><b>Exemple</b>∫₀² x² dx = 8/3.</div>"},{"t":"Propriétés","verrou":true},{"t":"Inverser les bornes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":53,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Le débit d'une pompe, à Ngaoundéré, varie selon la loi d(t) = 3t² (litres par heure).","tache":"Calcule le volume pompé entre t = 1 et t = 2."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r54",{"duree":25,"titre":"Calculs d'aires et de volumes","accroche":"De la formule au nombre de mètres carrés.","intro":"L'intégrale permet de calculer des aires limitées par des courbes et le volume de solides de révolution.","objectifs":["calculer une aire","calculer une aire entre deux courbes","calculer un volume de révolution"],"parties":[{"t":"Aire sous une courbe","html":"<div class='def'><b>Propriété</b>Si f est continue et positive sur [a ; b], l'<strong>aire</strong> du domaine compris entre la courbe, l'axe des abscisses et les droites x = a et x = b vaut <strong>∫ₐᵇ f(x) dx</strong> unités d'aire.</div>"},{"t":"Entre deux courbes","verrou":true},{"t":"Volume de révolution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":54,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un artisan de Bamenda veut calculer la surface d'un dessin délimité par y = x et y = x² sur [0 ; 1], l'unité valant 1 m.","tache":"Calcule cette aire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r55",{"duree":20,"titre":"Positivité et inégalité de la moyenne","accroche":"Encadrer une intégrale sans la calculer.","intro":"Il n'est pas toujours possible de calculer une intégrale exactement. Les inégalités donnent un encadrement.","objectifs":["utiliser la positivité","appliquer l'inégalité de la moyenne","calculer une valeur moyenne"],"parties":[{"t":"Positivité","html":"<div class='def'><b>Propriété</b>Si a ≤ b et f ≥ 0 sur [a ; b], alors <strong>∫ₐᵇ f ≥ 0</strong>. Si f ≤ g, alors ∫f ≤ ∫g.</div>"},{"t":"Inégalité de la moyenne","verrou":true},{"t":"La valeur moyenne","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":55,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un capteur enregistre la température d'une serre à Dschang, entre 20 °C et 30 °C, sur 10 heures.","tache":"Encadre l'intégrale de la température."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r56",{"duree":25,"titre":"Méthodes de calcul des intégrales","accroche":"Quand aucune primitive n'apparaît, on intègre par parties.","intro":"Les formes composées et l'intégration par parties permettent de calculer de nombreuses intégrales.","objectifs":["reconnaître une forme composée","appliquer l'intégration par parties","linéariser avant d'intégrer"],"parties":[{"t":"Intégration par parties","html":"<div class='def'><b>Formule</b>Si u et v sont dérivables, à dérivées continues, <strong>∫ₐᵇ u v' = [uv]ₐᵇ − ∫ₐᵇ u' v</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Linéarisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":56,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La puissance d'un panneau solaire de Maroua, au démarrage, vaut p(t) = t eᵗ (en kW, t en heures). On veut l'énergie produite pendant la première heure, E = ∫₀¹ t eᵗ dt.","tache":"Calcule E par intégration par parties."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r57",{"duree":20,"titre":"Valeurs approchées d'une intégrale","accroche":"Remplacer une courbe par des rectangles.","intro":"Quand une primitive n'est pas accessible, on approche l'intégrale par des aires simples.","objectifs":["appliquer la méthode des rectangles","appliquer la méthode des trapèzes","comparer les résultats"],"parties":[{"t":"Les rectangles","html":"<div class='def'><b>Méthode</b>On découpe [a ; b] en n intervalles de largeur h = (b − a) / n. L'intégrale est approchée par la <strong>somme des aires de rectangles</strong>.</div>"},{"t":"Les trapèzes","verrou":true},{"t":"Comparer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":57,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Un topographe de Kribi évalue la surface d'une parcelle à bord courbe à partir de mesures tous les 5 m.","tache":"Quelle méthode permet d'estimer cette surface ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r60",{"duree":15,"titre":"Équations différentielles : présentation","accroche":"Une équation dont l'inconnue est une fonction.","intro":"De nombreux phénomènes s'expriment par une relation entre une grandeur et sa vitesse de variation.","objectifs":["définir une équation différentielle","vérifier une solution","comprendre une condition initiale"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>équation différentielle</strong> relie une fonction inconnue y à ses dérivées. Résoudre, c'est trouver toutes les fonctions qui la vérifient.</div>"},{"t":"Vérifier","verrou":true},{"t":"Condition initiale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":60,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Une équipe de santé de Bertoua modélise la croissance d'une culture par une équation liant sa taille et sa vitesse de croissance.","tache":"Vérifie que y = e^(2x) convient pour y' = 2y."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r61",{"duree":25,"titre":"Équations y' = ay et y' = ay + b","accroche":"Le refroidissement d'une tasse, en une formule.","intro":"Ces équations décrivent les croissances, les décroissances et les refroidissements.","objectifs":["résoudre y' = ay","résoudre y' = ay + b","utiliser une condition initiale"],"parties":[{"t":"L'équation y' = ay","html":"<div class='def'><b>Théorème</b>Les solutions de <strong>y' = ay</strong> sont les fonctions <strong>y(x) = C e^(ax)</strong>, avec C constante réelle.</div>"},{"t":"L'équation y' = ay + b","verrou":true},{"t":"Condition initiale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":61,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"La température d'un bouillon servi à Bafia baisse selon une équation de la forme y' = −0,1 y, où y est l'écart avec la pièce.","tache":"Donne l'expression de y si l'écart initial est 60 °C."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-maths-r62",{"duree":25,"titre":"Équations du type y'' + ay' + by = 0","accroche":"Un ressort qui oscille obéit à cette équation.","intro":"Ces équations décrivent les oscillations mécaniques et électriques.","objectifs":["écrire l'équation caractéristique","résoudre y'' + ω²y = 0","traiter les conditions initiales"],"parties":[{"t":"Équation caractéristique","html":"<div class='def'><b>Méthode</b>L'<strong>équation caractéristique</strong> de y'' + ay' + by = 0 est <strong>r² + ar + b = 0</strong>.</div><ul><li>Δ > 0 : y = Ae^(r₁x) + Be^(r₂x).</li><li>Δ = 0 : y = (Ax + B)e^(rx).</li><li>Δ < 0 : y = e^(αx)(A cos βx + B sin βx).</li></ul>"},{"t":"L'équation y'' + ω²y = 0","verrou":true},{"t":"Conditions initiales","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"maths","rang":62,"apc":{"module":"Mathématiques de Terminale","famille":"Résolution de problèmes issus de la vie courante et des sciences","agir":"Modéliser, calculer et interpréter","situation":"Pour un projet de sismographe artisanal à Limbé, une masse suspendue à un ressort suit l'équation y'' + 4y = 0.","tache":"Exprime y si y(0) = 1 et y'(0) = 0."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r01",{"duree":20,"titre":"Erreur et incertitude sur la mesure","accroche":"Une mesure sans incertitude ne dit pas grand-chose.","intro":"Toute mesure comporte une part d'imprécision. Savoir l'évaluer permet de comparer une valeur à une référence.","objectifs":["distinguer erreur et incertitude","calculer une incertitude relative","présenter un résultat"],"parties":[{"t":"Erreur et incertitude","html":"<div class='def'><b>Définitions</b>L'<strong>incertitude absolue</strong> ΔX est la limite de l'écart possible entre la valeur mesurée et la valeur vraie. L'<strong>incertitude relative</strong> est ΔX / X.</div>"},{"t":"Présenter un résultat","html":"<p class='formule'>X = x ± ΔX</p><div class='ex'><b>Exemple</b>L = 20,0 ± 0,5 cm : l'incertitude relative est de 2,5 %.</div>","labo":{"type":"calcul","f":"incert","vals":{"x":20,"d":0.5}}},{"t":"Propagation","html":"<p>Pour une somme, les incertitudes absolues s'ajoutent. Pour un produit ou un quotient, les incertitudes relatives s'ajoutent.</p>","retenir":"Une erreur peut être systématique ou aléatoire."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> L'incertitude absolue sur une mesure s'exprime :</p><ol type='a'><li>en pourcentage de la valeur mesurée, obligatoirement</li><li>sans unité, car c'est un simple écart</li><li>dans la même unité que la grandeur mesurée</li><li>en secondes, quelle que soit la grandeur</li></ol><details><summary>Voir la réponse</summary><p><strong>dans la même unité que la grandeur mesurée</strong>. Ex. : L = 12,4 cm ± 0,1 cm.</p></details><p><strong>Application directe des savoirs.</strong></p><p>m = 50 ± 1 g : calcule l'incertitude relative.</p><details><summary>Voir la réponse</summary><p>(Réponse : 2 %.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Deux groupes mesurent g avec un pendule. Groupe A : g = (9,79 ± 0,05) m/s² ; groupe B : g = (9,6 ± 0,1) m/s². La valeur de référence au lieu de mesure est 9,78 m/s².</p><p><strong>Consigne 1.</strong> Examine si chaque résultat est compatible avec la valeur de référence.</p><p><strong>Consigne 2.</strong> Calcule l'incertitude relative de chaque groupe et dis lequel est le plus précis.</p><details><summary>Voir une réponse attendue</summary><p>A : [9,74 ; 9,84] contient 9,78, compatible. B : [9,5 ; 9,7] ne la contient pas, non compatible (erreur systématique probable). Incertitudes relatives : A 0,05/9,79 ≈ 0,5 % ; B 0,1/9,6 ≈ 1 % : A est plus précis.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["X = x ± ΔX.","Incertitude relative.","Propagation."],"exo":"<p>m = 50 ± 1 g : calcule l'incertitude relative. <em>(Réponse : 2 %.)</em></p>","quiz":[{"q":"L'incertitude absolue sur une mesure s'exprime :","r":["en pourcentage de la valeur mesurée, obligatoirement","sans unité, car c'est un simple écart","dans la même unité que la grandeur mesurée","en secondes, quelle que soit la grandeur"],"b":2,"e":"Ex. : L = 12,4 cm ± 0,1 cm."},{"q":"L'incertitude relative est :","r":["la différence X − ΔX","le produit X × ΔX","toujours égale à 1 %","le rapport ΔX / X"],"b":3,"e":"Elle s'exprime souvent en pourcentage."},{"q":"L = 20,0 cm ± 0,2 cm : l'incertitude relative vaut :","r":["1 %","0,2 %","2 %","10 %"],"b":0,"e":"0,2 ÷ 20,0 = 0,01."},{"q":"Une erreur systématique :","r":["varie au hasard d'une mesure à l'autre","décale toutes les mesures dans le même sens","disparaît quand on répète les mesures et fait la moyenne","n'existe pas avec un appareil numérique"],"b":1,"e":"Ex. : un zéro mal réglé sur une balance."},{"q":"Une erreur aléatoire se réduit :","r":["en changeant d'unité pour exprimer le résultat","en arrondissant chaque mesure à l'unité","en répétant les mesures et en prenant la moyenne","jamais, l'erreur aléatoire étant toujours la même"],"b":2,"e":"Les écarts dans les deux sens se compensent."},{"q":"Le résultat 9,81 m/s² comporte :","r":["2 chiffres significatifs","4 chiffres significatifs","1 chiffre significatif","3 chiffres significatifs"],"b":3,"e":"9, 8 et 1 sont significatifs."},{"q":"Pour une somme S = A + B, l'incertitude absolue vaut :","r":["ΔA + ΔB","ΔA × ΔB","ΔA − ΔB","ΔA / ΔB"],"b":0,"e":"Les incertitudes absolues s'additionnent."},{"q":"Pour un produit P = A × B, l'incertitude relative vaut :","r":["ΔA + ΔB","ΔA/A + ΔB/B","ΔA × ΔB","ΔA/A − ΔB/B"],"b":1,"e":"Les incertitudes relatives s'additionnent."},{"q":"Un chronomètre gradué au centième de seconde a une incertitude de lecture d'environ :","r":["1 s","0,1 s","0,01 s","0,001 s"],"b":2,"e":"Elle correspond à la plus petite graduation."},{"q":"Le résultat d'une mesure s'écrit :","r":["valeur seule, avec tous les chiffres de la calculatrice","incertitude seule, exprimée en pourcentage","valeur ± incertitude, sans unité","valeur ± incertitude, avec l'unité"],"b":3,"e":"C'est l'écriture scientifique attendue."}],"c":"Tle C","m":"physique","rang":1,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Au lycée de Nkolbisson, deux groupes mesurent la même longueur d'onde et trouvent des valeurs proches. Ils s'interrogent sur leur accord avec l'indication du fabricant.","tache":"Dis comment décider si l'écart est acceptable."},"gratuit":true});
VRT_L("tle-c-physique-r02",{"duree":15,"titre":"Dimensions et homogénéité","accroche":"Vérifier une formule sans refaire la démonstration.","intro":"Une formule juste doit avoir la même dimension des deux côtés. Ce contrôle détecte beaucoup d'erreurs.","objectifs":["écrire une dimension","vérifier l'homogénéité","trouver l'unité d'une constante"],"parties":[{"t":"Dimension","html":"<div class='def'><b>Définition</b>La <strong>dimension</strong> d'une grandeur s'exprime à partir des grandeurs de base : [L], [M], [T], [I]. Une relation est <strong>homogène</strong> si les deux membres ont la même dimension.</div>"},{"t":"Exemples","verrou":true},{"t":"Remarque d'examen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":2,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un élève de Dschang propose T = 2π√(g/L) pour la période d'un pendule.","tache":"Vérifie si cette formule est possible."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r03",{"duree":20,"titre":"La force de gravitation","accroche":"La même force fait tomber une mangue et tourner la Lune.","intro":"Newton a montré que tous les corps s'attirent selon une même loi.","objectifs":["énoncer la loi d'attraction","calculer une force","représenter les vecteurs"],"parties":[{"t":"La loi","html":"<div class='def'><b>Loi d'attraction universelle</b>Deux corps ponctuels de masses m et m', distants de d, s'attirent avec une force d'intensité <strong>F = G m m' / d²</strong>, où G = 6,67 × 10⁻¹¹ N·m²·kg⁻².</div>"},{"t":"Caractéristiques","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":3,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Pour un club d'astronomie à Maroua, on souhaite comparer l'attraction de la Terre sur un satellite à deux altitudes.","tache":"Explique comment varie la force quand l'altitude augmente."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r04",{"duree":20,"titre":"Le champ de gravitation","accroche":"g n'est pas le même au sommet du mont Cameroun et à Douala.","intro":"Autour d'une planète, chaque point de l'espace est caractérisé par un champ de gravitation.","objectifs":["définir le champ","calculer g en altitude","relier g et g₀"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>champ de gravitation</strong> créé par une masse M à la distance d a pour intensité <strong>g = GM / d²</strong>. Il est dirigé vers le centre de M.</div>"},{"t":"En altitude","verrou":true},{"t":"Rappel","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":4,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un randonneur grimpe sur le mont Cameroun avec un dynamomètre pour comparer son poids.","tache":"Dis comment évolue le poids avec l'altitude."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r05",{"duree":20,"titre":"Charge électrique et loi de Coulomb","accroche":"Une règle frottée attire de petits morceaux de papier.","intro":"Les charges électriques exercent des forces à distance. La loi de Coulomb les quantifie.","objectifs":["expliquer l'électrisation","énoncer la loi de Coulomb","calculer une force"],"parties":[{"t":"L'électrisation","html":"<div class='def'><b>Loi de Coulomb</b>Deux charges ponctuelles q et q', séparées d'une distance d, exercent l'une sur l'autre des forces d'intensité <strong>F = k |q q'| / d²</strong>, avec k = 9 × 10⁹ S.I.</div><p>Les charges de même signe se repoussent, celles de signes contraires s'attirent.</p>"},{"t":"Les modes d'électrisation","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":5,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Par temps sec, à Garoua, un élève reçoit une petite décharge en touchant une poignée métallique.","tache":"Explique le phénomène."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r06",{"duree":20,"titre":"Champ électrostatique et condensateur plan","accroche":"Entre deux plaques, le champ est uniforme.","intro":"Une charge crée un champ électrique. Entre les armatures d'un condensateur plan, ce champ est uniforme.","objectifs":["définir le champ électrique","calculer E dans un condensateur","calculer une force"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>champ électrostatique</strong> E en un point vérifie <strong>F = qE</strong>. Pour une charge ponctuelle Q : E = k|Q| / d².</div>"},{"t":"Condensateur plan","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":6,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un appareil de physique du lycée de Mbouda, on applique 100 V entre deux plaques distantes de 1 cm.","tache":"Calcule le champ électrique."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r07",{"duree":20,"titre":"Force et champ magnétiques d'un courant","accroche":"Un fil parcouru par un courant dévie une boussole.","intro":"Un courant crée un champ magnétique. Ce champ exerce à son tour une force sur d'autres courants.","objectifs":["calculer B d'un fil et d'un solénoïde","appliquer la force de Laplace","orienter les vecteurs"],"parties":[{"t":"Champs créés","html":"<div class='def'><b>Formules</b>Un fil rectiligne crée un champ <strong>B = 2 × 10⁻⁷ I / d</strong>. Dans un solénoïde long : <strong>B = 4π × 10⁻⁷ N I / L</strong>.</div>"},{"t":"Force de Laplace","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":7,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un électricien de Douala observe qu'une boussole dévie près d'un gros câble parcouru par un courant.","tache":"Explique la déviation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r08",{"duree":20,"titre":"Interaction de courants et force de Lorentz","accroche":"Une particule chargée dévie sans ralentir.","intro":"Deux conducteurs parcourus par des courants interagissent. Une charge mobile subit la force de Lorentz.","objectifs":["décrire l'interaction de deux fils","écrire la force de Lorentz","orienter la force"],"parties":[{"t":"Interaction entre fils","html":"<div class='def'><b>Force de Lorentz</b>Une particule de charge q, de vitesse v, dans un champ B, subit la force <strong>F = q v ∧ B</strong>, d'intensité |q| v B sin α.</div><p>Deux fils parallèles parcourus par des courants de même sens s'attirent.</p>"},{"t":"Interaction","verrou":true},{"t":"Propriété","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":8,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un exposé sur les aurores, un élève de Bertoua explique que des particules du Soleil sont déviées par le champ magnétique terrestre.","tache":"Identifie la force responsable."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r10",{"duree":25,"titre":"Mouvement rectiligne d'un solide","accroche":"Un plan incliné, des frottements et une accélération à trouver.","intro":"Le théorème du centre d'inertie permet de trouver l'accélération d'un solide.","objectifs":["appliquer le théorème du centre d'inertie","calculer une accélération","écrire les équations horaires"],"parties":[{"t":"Méthode","html":"<div class='def'><b>Théorème du centre d'inertie</b>Dans un référentiel galiléen, <strong>ΣF = m a</strong>.</div><ol><li>Choisir le système et le référentiel.</li><li>Faire le bilan des forces.</li><li>Projeter.</li></ol>"},{"t":"Plan incliné","verrou":true},{"t":"Équations horaires","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":10,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un mototaxi de Douala freine sur une route en pente. Un élève veut estimer sa décélération.","tache":"Indique la méthode."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r11",{"duree":25,"titre":"Mouvement plan dans le champ de pesanteur","accroche":"La portée maximale d'un tir se calcule.","intro":"Un projectile décrit une parabole. Chaque composante du mouvement s'étudie séparément.","objectifs":["établir les équations horaires","écrire la trajectoire","calculer portée et flèche"],"parties":[{"t":"Équations horaires","html":"<div class='def'><b>Résultat</b>Sans frottement, l'accélération vaut <strong>g</strong>. Pour une vitesse initiale v₀ d'angle α : x = v₀ cos α · t et y = −(1/2) g t² + v₀ sin α · t.</div>"},{"t":"Trajectoire","verrou":true},{"t":"Portée et flèche","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":11,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Lors d'un match au stade de Bafoussam, un joueur frappe le ballon à 20 m/s, sous un angle de 45°.","tache":"Calcule la portée, sans frottement, avec g = 10 m/s²."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r13",{"duree":25,"titre":"Mouvement dans un champ électrique","accroche":"Un faisceau d'électrons dévié sur un écran.","intro":"Une particule chargée dans un champ uniforme se comporte comme un projectile.","objectifs":["calculer l'accélération","établir la trajectoire","calculer une vitesse par l'énergie"],"parties":[{"t":"Accélération","html":"<div class='def'><b>Résultat</b>Une particule de charge q, de masse m, dans un champ E, a pour accélération <strong>a = qE / m</strong>. Le poids est généralement négligé.</div>"},{"t":"Accélération par une tension","html":"<p class='formule'>(1/2) m v² = |q| U</p>","labo":{"type":"calcul","f":"conde","vals":{"U":200,"d":10}}},{"t":"Déviation","html":"<p>Avec une vitesse initiale perpendiculaire à E, la trajectoire est parabolique.</p><p class='formule'>y = q E x² / (2 m v₀²)</p>","retenir":"Une tension accélère les particules chargées."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Une particule chargée entrant parallèlement aux armatures d'un condensateur a une trajectoire :</p><ol type='a'><li>circulaire entre les armatures</li><li>rectiligne et accélérée vers l'armature</li><li>hélicoïdale autour des lignes de champ</li><li>parabolique entre les armatures</li></ol><details><summary>Voir la réponse</summary><p><strong>parabolique entre les armatures</strong>. Le champ uniforme joue le rôle de la pesanteur.</p></details><p><strong>Application directe des savoirs.</strong></p><p>Écris l'expression de v pour un électron accéléré sous U.</p><details><summary>Voir la réponse</summary><p>(Réponse : v = √(2eU/m).)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Dans un oscilloscope, un électron entre à 2,0 × 10⁷ m/s entre deux plaques de 5,0 cm de long, distantes de 2,0 cm, sous 200 V, à égale distance des plaques. e = 1,6 × 10⁻¹⁹ C ; m = 9,1 × 10⁻³¹ kg. Mbida pense qu'il heurtera une plaque.</p><p><strong>Consigne 1.</strong> Calcule l'accélération de l'électron entre les plaques.</p><p><strong>Consigne 2.</strong> Examine si l'électron sort sans toucher les plaques.</p><details><summary>Voir une réponse attendue</summary><p>a = eU/(md) = 1,6 × 10⁻¹⁹ × 200/(9,1 × 10⁻³¹ × 0,02) ≈ 1,76 × 10¹⁵ m/s². Durée de traversée : 0,05/2 × 10⁷ = 2,5 × 10⁻⁹ s ; déviation y = ½at² ≈ 5,5 mm, inférieure à 1 cm : il sort sans toucher, Mbida se trompe.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la démarche scientifique."}],"revision":["a = qE/m.","Énergie : (1/2) mv² = |q|U.","Trajectoire parabolique."],"exo":"<p>Écris l'expression de v pour un électron accéléré sous U. <em>(Réponse : v = √(2eU/m).)</em></p>","quiz":[{"q":"Une particule chargée entrant parallèlement aux armatures d'un condensateur a une trajectoire :","r":["circulaire entre les armatures","rectiligne et accélérée vers l'armature","hélicoïdale autour des lignes de champ","parabolique entre les armatures"],"b":3,"e":"Le champ uniforme joue le rôle de la pesanteur."},{"q":"L'accélération d'une particule de charge q et de masse m dans un champ E vaut :","r":["q E / m","m E / q","q m E","E / q"],"b":0,"e":"On applique F = ma avec F = qE."},{"q":"Un électron accéléré depuis le repos sous une tension U acquiert une vitesse :","r":["eU / m","√(2eU / m)","2eU m","√(m / eU)"],"b":1,"e":"On applique le théorème de l'énergie cinétique : ½mv² = eU."},{"q":"La déviation électrique est utilisée dans :","r":["le moteur à essence à quatre temps","la balance de Roberval","l'oscilloscope à tube cathodique","le thermomètre à mercure"],"b":2,"e":"Le faisceau d'électrons est dévié par des plaques."},{"q":"La déflexion verticale à la sortie des plaques est proportionnelle à :","r":["la masse uniquement","la couleur du faisceau","la longueur du fil d'alimentation","la tension appliquée aux plaques"],"b":3,"e":"C'est le principe de la mesure à l'oscilloscope."},{"q":"Le poids d'un électron est négligeable devant la force électrique car :","r":["sa masse est très petite (9,1 × 10⁻³¹ kg)","sa charge est nulle comparée à sa masse","g est nul dans le vide du tube","E est nul entre les armatures"],"b":0,"e":"mg ≈ 9 × 10⁻³⁰ N contre eE ≈ 10⁻¹⁵ N."},{"q":"Entre les plaques, le mouvement parallèle aux armatures est :","r":["accéléré","uniforme","nul","circulaire"],"b":1,"e":"Aucune force n'agit dans cette direction."},{"q":"Un ion positif est dévié :","r":["en sens contraire de E","pas du tout","dans le sens du champ E","perpendiculairement à E dans le plan des plaques"],"b":2,"e":"F = qE avec q > 0."},{"q":"L'énergie cinétique gagnée par une charge q sous une tension U vaut :","r":["q / U","U / q","q U²","|q| U"],"b":3,"e":"C'est le travail de la force électrique."},{"q":"Un électron accéléré sous 100 V gagne :","r":["100 eV","1 eV","1,6 × 10⁻¹⁷ eV","10 000 eV"],"b":0,"e":"W = eU = 100 eV."}],"c":"Tle C","m":"physique","rang":13,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un ancien téléviseur étudié au lycée technique de Douala, un faisceau d'électrons est dévié.","tache":"Explique pourquoi la trajectoire est courbée."},"gratuit":true});
VRT_L("tle-c-physique-r14",{"duree":25,"titre":"Mouvement dans un champ magnétique","accroche":"Séparer des isotopes grâce à la courbure de leur trajectoire.","intro":"Dans un champ magnétique uniforme, une particule chargée décrit un cercle.","objectifs":["établir le rayon de la trajectoire","calculer une période","appliquer au spectrographe"],"parties":[{"t":"Mouvement circulaire","html":"<div class='def'><b>Résultat</b>Avec v perpendiculaire à B, le mouvement est <strong>circulaire uniforme</strong> de rayon <strong>R = m v / (|q| B)</strong>.</div>"},{"t":"Période","verrou":true},{"t":"Spectrographe de masse","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":14,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Lors d'un concours scientifique, deux candidats, Akono et Benji, cherchent la tension qui dirige des ions dans un trou donné.","tache":"Présente les relations à utiliser."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r15",{"duree":15,"titre":"Généralités sur les systèmes oscillants","accroche":"Un balancier, un ressort, une corde de guitare : même idée.","intro":"Les systèmes oscillants reviennent périodiquement à leur position d'équilibre.","objectifs":["définir une oscillation","définir période et amplitude","lire une élongation"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Un <strong>système oscillant</strong> effectue un mouvement de va-et-vient autour d'une position d'équilibre. La <strong>période</strong> T est la durée d'une oscillation.</div>"},{"t":"Élongation","verrou":true},{"t":"Types d'oscillations","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":15,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un ingénieur stagiaire de Limbé observe les oscillations d'un pont piéton lorsque des personnes marchent en cadence.","tache":"Dis quel type d'oscillation est en jeu."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r18",{"duree":25,"titre":"Pendule simple, amortissement et résonance","accroche":"La longueur règle le rythme d'un pendule.","intro":"Le pendule simple est un oscillateur classique : sa période dépend seulement de sa longueur et de g.","objectifs":["établir la période","définir l'amortissement","définir la résonance"],"parties":[{"t":"Le pendule simple","html":"<div class='def'><b>Résultat</b>Pour de faibles oscillations, la période d'un <strong>pendule simple</strong> est <strong>T = 2π √(L / g)</strong>.</div>"},{"t":"Exemple","verrou":true},{"t":"Amortissement et résonance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":18,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un horloger du marché Mokolo veut régler une horloge qui retarde.","tache":"Dis s'il doit raccourcir ou allonger le balancier."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r19",{"duree":25,"titre":"Le condensateur : charge, décharge et énergie","accroche":"Le flash d'un appareil photo stocke l'énergie d'un condensateur.","intro":"Un condensateur accumule des charges, puis les libère. Le temps caractéristique dépend de R et C.","objectifs":["relier q, C et U","décrire la charge","calculer l'énergie stockée"],"parties":[{"t":"Capacité","html":"<div class='def'><b>Définition</b>La <strong>capacité</strong> C d'un condensateur relie sa charge à sa tension : <strong>Q = C U</strong>. Elle s'exprime en farads.</div>"},{"t":"Charge et décharge","verrou":true},{"t":"Énergie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":19,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un réparateur de Douala doit changer un condensateur d'un poste radio. Il manipule un condensateur chargé.","tache":"Explique pourquoi il doit d'abord le décharger."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r26",{"duree":15,"titre":"La stroboscopie","accroche":"Un ventilateur qui semble immobile.","intro":"Une lumière clignotante peut donner l'illusion d'un mouvement arrêté ou ralenti.","objectifs":["définir la stroboscopie","obtenir l'immobilité apparente","mesurer une fréquence"],"parties":[{"t":"Principe","html":"<div class='def'><b>Définition</b>La <strong>stroboscopie</strong> consiste à éclairer un objet en mouvement périodique par des éclairs brefs et réguliers.</div>"},{"t":"Immobilité apparente","verrou":true},{"t":"Mouvement ralenti","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":26,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un réparateur de ventilateurs de Bafang veut mesurer la vitesse de rotation de son moteur sans le toucher.","tache":"Propose une méthode."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r27",{"duree":25,"titre":"Ondes progressives","accroche":"L'onde avance, la matière reste sur place.","intro":"Une onde mécanique transporte de l'énergie sans transporter de matière.","objectifs":["distinguer ondes transversales et longitudinales","utiliser λ = v/f","comparer le mouvement de deux points"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une <strong>onde mécanique</strong> est la propagation d'une perturbation dans un milieu matériel, sans transport de matière. Elle est <strong>transversale</strong> ou <strong>longitudinale</strong>.</div>"},{"t":"Grandeurs","verrou":true},{"t":"Comparer deux points","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":27,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un musicien de Bafoussam accorde son balafon. Il cherche la longueur d'onde d'un son de 440 Hz dans l'air.","tache":"Calcule-la avec v = 340 m/s."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r28",{"duree":25,"titre":"Superposition et interférences mécaniques","accroche":"Deux ondes peuvent s'additionner ou s'annuler.","intro":"Là où deux ondes se croisent, leurs effets s'additionnent et dessinent des franges.","objectifs":["énoncer le principe de superposition","définir les interférences","calculer un état vibratoire"],"parties":[{"t":"Superposition","html":"<div class='def'><b>Principe</b>En un point atteint par deux ondes, l'élongation résultante est la <strong>somme des élongations</strong>.</div>"},{"t":"Interférences","verrou":true},{"t":"Construction de Fresnel","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":28,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Deux pointes fixées à un diapason de 200 Hz frappent une surface d'eau. La vitesse des ondes est 0,4 m/s.","tache":"Détermine l'état d'un point situé à 18 mm d'une source et à 9 mm de l'autre."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r29",{"duree":25,"titre":"Diffraction et interférences lumineuses","accroche":"La lumière se comporte comme une onde.","intro":"Les expériences de diffraction et d'interférences révèlent la nature ondulatoire de la lumière.","objectifs":["décrire la diffraction","utiliser l'interfrange","calculer une longueur d'onde"],"parties":[{"t":"Diffraction","html":"<div class='def'><b>Définition</b>La <strong>diffraction</strong> est le phénomène d'étalement d'une onde au passage d'un obstacle ou d'une ouverture de faible dimension.</div>"},{"t":"Interférences de Young","html":"<p class='formule'>δ = a x / D ; i = λ D / a</p><p>Frange brillante : δ = kλ.</p>","labo":{"type":"calcul","f":"young","vals":{"l":600,"D":1.5,"a":0.2}}},{"t":"Exemple","html":"<p>λ = 600 nm, D = 1 m, a = 1 mm : i = 0,6 mm.</p><div class='ex'><b>Type bac</b>Si 6 interfranges mesurent 28,5 mm, alors i = 4,75 mm.</div>","retenir":"Pour mesurer i, on mesure plusieurs interfranges."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> La diffraction de la lumière par une fente montre que :</p><ol type='a'><li>la lumière est une onde</li><li>la lumière est formée de grains uniquement</li><li>la lumière ne se propage pas</li><li>la fente émet de la lumière</li></ol><details><summary>Voir la réponse</summary><p><strong>la lumière est une onde</strong>. L'onde s'étale derrière l'obstacle.</p></details><p><strong>Application directe des savoirs.</strong></p><p>i = 2 mm, D = 1 m, a = 0,3 mm : calcule λ.</p><details><summary>Voir la réponse</summary><p>(Réponse : 600 nm.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Un laser porte l'étiquette « 532 nm ». Avec des fentes de Young (a = 0,20 mm), on mesure un interfrange de 6,5 mm sur un écran à 2,0 m. Kamdem accuse l'étiquette d'être fausse ; Toko accuse la mesure.</p><p><strong>Consigne 1.</strong> Calcule la longueur d'onde à partir de la mesure.</p><p><strong>Consigne 2.</strong> Départage Kamdem et Toko et calcule la largeur de la tache centrale de diffraction derrière une fente de 0,10 mm.</p><details><summary>Voir une réponse attendue</summary><p>λ = a·i/D = 0,2 × 10⁻³ × 6,5 × 10⁻³/2 = 6,5 × 10⁻⁷ m = 650 nm : lumière rouge, pas verte (532 nm). Si la mesure est soignée, l'étiquette est fausse : Kamdem a raison. Tache centrale : 2λD/a = 2 × 650 × 10⁻⁹ × 2/10⁻⁴ ≈ 2,6 cm.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["Diffraction.","i = λD/a.","δ = kλ."],"exo":"<p>i = 2 mm, D = 1 m, a = 0,3 mm : calcule λ. <em>(Réponse : 600 nm.)</em></p>","quiz":[{"q":"La diffraction de la lumière par une fente montre que :","r":["la lumière est une onde","la lumière est formée de grains uniquement","la lumière ne se propage pas","la fente émet de la lumière"],"b":0,"e":"L'onde s'étale derrière l'obstacle."},{"q":"La diffraction est d'autant plus marquée que la fente est :","r":["large","étroite","longue","colorée"],"b":1,"e":"Le demi-angle de diffraction vaut environ λ/a."},{"q":"Le demi-angle de diffraction θ par une fente de largeur a vaut :","r":["a / λ","λ a","λ / a","a"],"b":2,"e":"θ en radians, pour de petits angles."},{"q":"L'expérience des fentes de Young produit :","r":["une tache lumineuse unique, uniforme et très brillante au centre","aucune lumière sur l'écran","un arc-en-ciel uniquement, sans franges","des franges alternativement brillantes et sombres"],"b":3,"e":"Ce sont des interférences lumineuses."},{"q":"L'interfrange vaut :","r":["i = λ D / a","i = a D / λ","i = λ a / D","i = D"],"b":0,"e":"a est la distance entre les fentes."},{"q":"Avec λ = 600 nm, D = 2 m et a = 1 mm, l'interfrange vaut :","r":["12 mm","1,2 mm","0,12 mm","1,2 m"],"b":1,"e":"600 × 10⁻⁹ × 2 / 10⁻³ = 1,2 × 10⁻³ m."},{"q":"Si on rapproche les fentes, l'interfrange :","r":["diminue","ne change pas","augmente","s'annule"],"b":2,"e":"i est inversement proportionnel à a."},{"q":"La lumière visible a des longueurs d'onde comprises entre environ :","r":["4 mm et 8 mm","400 m et 800 m","4 nm et 8 nm","400 nm et 800 nm"],"b":3,"e":"Du violet au rouge."},{"q":"Avec de la lumière blanche, les franges sont :","r":["irisées (colorées)","noires et blanches uniquement","absentes","toutes rouges"],"b":0,"e":"Chaque couleur a son interfrange."},{"q":"La frange centrale est :","r":["sombre","brillante","absente","colorée en bleu"],"b":1,"e":"La différence de marche y est nulle."}],"c":"Tle C","m":"physique","rang":29,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Le lycée de Nkola a reçu un laser dont la fréquence indiquée doit être vérifiée. Les élèves mesurent 6 interfranges, avec a = 0,2 mm et D = 1,5 m.","tache":"Explique comment calculer la longueur d'onde."},"gratuit":true});
VRT_L("tle-c-physique-r31",{"duree":25,"titre":"L'effet photoélectrique","accroche":"La lumière peut arracher des électrons à un métal.","intro":"Einstein a expliqué ce phénomène par l'existence de photons.","objectifs":["définir l'effet photoélectrique","énoncer l'équation d'Einstein","calculer une énergie cinétique"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet photoélectrique</strong> est l'extraction d'électrons d'un métal éclairé par une radiation de fréquence suffisante.</div>"},{"t":"Équation d'Einstein","verrou":true},{"t":"Le seuil","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":31,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un laboratoire du lycée de Bafoussam, on éclaire une cellule dont le travail d'extraction est 1,8 eV avec une lumière de 633 nm.","tache":"Dis si des électrons sont émis."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r34",{"duree":25,"titre":"Le noyau atomique","accroche":"La masse d'un noyau est inférieure à celle de ses nucléons.","intro":"Le défaut de masse correspond à l'énergie qui lie les nucléons.","objectifs":["décrire le noyau","calculer un défaut de masse","comparer la stabilité"],"parties":[{"t":"Constitution","html":"<div class='def'><b>Définitions</b>Un noyau ᴬ_Z X contient Z protons et N = A − Z neutrons. Des <strong>isotopes</strong> ont le même Z et des A différents.</div>"},{"t":"Énergie de liaison","verrou":true},{"t":"Stabilité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":34,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un cours sur l'énergie à Yaoundé, on compare la stabilité de plusieurs noyaux.","tache":"Dis quelle grandeur permet la comparaison."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r35",{"duree":20,"titre":"La radioactivité : les réactions nucléaires","accroche":"Un noyau peut se transformer spontanément.","intro":"Les noyaux instables se désintègrent en émettant des particules. Leur équation se déduit de lois de conservation.","objectifs":["définir la radioactivité","citer les types","écrire une équation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>radioactivité</strong> est la désintégration spontanée d'un noyau instable, en émettant des particules et souvent un rayonnement γ.</div>"},{"t":"Types","verrou":true},{"t":"Lois de conservation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":35,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un hôpital de Yaoundé, un technicien explique qu'un traceur médical se transforme naturellement dans le temps.","tache":"Écris les règles à respecter pour une équation nucléaire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r36",{"duree":25,"titre":"Activité et loi de décroissance radioactive","accroche":"La moitié des noyaux disparaît à chaque demi-vie.","intro":"La décroissance radioactive suit une loi exponentielle, utilisée aussi pour la datation.","objectifs":["énoncer la loi","calculer une activité","calculer une date"],"parties":[{"t":"La loi","html":"<div class='def'><b>Loi</b><strong>N(t) = N₀ e^(−λt)</strong>. La demi-vie vaut <strong>T = ln 2 / λ</strong>. L'activité vaut <strong>A = λN</strong>, en becquerels.</div>"},{"t":"Type bac","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":36,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un archéologue de Douala analyse des restes de bois dans un site ancien de l'Adamaoua.","tache":"Explique le principe de datation au carbone 14."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r37",{"duree":20,"titre":"Les réactions nucléaires provoquées","accroche":"Fusion dans le Soleil, fission dans les centrales.","intro":"Une réaction nucléaire peut être provoquée. Elle libère alors une énergie considérable.","objectifs":["distinguer fission et fusion","calculer l'énergie libérée","citer des applications"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>La <strong>fission</strong> est la rupture d'un noyau lourd sous l'impact d'un neutron. La <strong>fusion</strong> est l'union de deux noyaux légers.</div>"},{"t":"Énergie","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":37,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Lors d'un débat, Amina dit que le Soleil fonctionne « comme une centrale nucléaire » ; Paul répond que la centrale casse des noyaux lourds alors que le Soleil assemble des noyaux légers. On donne : ²³⁵U + n → ⁹⁴Sr + ¹⁴⁰Xe + 2n et 4 ¹H → ⁴He + 2 e⁺.","tache":"Départage Amina et Paul en nommant chaque réaction."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r38",{"duree":15,"titre":"Dangers des rayonnements et radioprotection","accroche":"Trois règles : temps, distance, écran.","intro":"Les rayonnements sont utiles en médecine, mais ils peuvent être dangereux. Il faut savoir s'en protéger.","objectifs":["citer les dangers","citer les moyens de protection","connaître les signes de danger"],"parties":[{"t":"Les dangers","html":"<div class='def'><b>Définition</b>L'<strong>exposition aux rayonnements ionisants</strong> peut léser les cellules et causer des brûlures ou des cancers. La dose s'évalue en sieverts.</div>"},{"t":"Se protéger","verrou":true},{"t":"Au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":38,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Des enfants ont trouvé près d'une ancienne décharge à Douala un objet portant le symbole radioactif.","tache":"Indique ce qu'il faut faire."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r09",{"duree":25,"titre":"Cinématique, lois de Newton et dynamique du solide","accroche":"Décrire, puis expliquer le mouvement.","intro":"Cette leçon rassemble la cinématique et les trois lois de Newton.","objectifs":["définir les paramètres cinématiques","énoncer les lois de Newton","appliquer le théorème du centre d'inertie"],"parties":[{"t":"Cinématique","html":"<div class='def'><b>Définitions</b>La <strong>vitesse</strong> est la dérivée du vecteur position, l'<strong>accélération</strong>, la dérivée du vecteur vitesse.</div>"},{"t":"Les lois de Newton","verrou":true},{"t":"Solide en rotation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":9,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un mécanicien de Douala étudie la rotation d'une roue qui ralentit à cause d'un frein.","tache":"Choisis la relation à appliquer."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r12",{"duree":25,"titre":"Pendule conique, virage et satellite","accroche":"La route relevée d'un virage a une raison physique.","intro":"Dans un mouvement circulaire uniforme, l'accélération est dirigée vers le centre.","objectifs":["utiliser a = v²/r","étudier un pendule conique","calculer l'inclinaison d'un virage"],"parties":[{"t":"Mouvement circulaire","html":"<div class='def'><b>Résultat</b>En mouvement circulaire uniforme, l'accélération est <strong>centripète</strong>, de valeur <strong>a = v² / r = ω² r</strong>.</div>"},{"t":"Pendule conique","verrou":true},{"t":"Virage et satellite","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":12,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Les ingénieurs d'un axe routier à Yaoundé conçoivent un virage de rayon 100 m pour une vitesse de 20 m/s.","tache":"Calcule l'inclinaison idéale, avec g = 10 m/s²."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r16",{"duree":25,"titre":"Le pendule élastique","accroche":"Une masse, un ressort et une équation différentielle.","intro":"Un oscillateur élastique obéit à une équation du second ordre.","objectifs":["établir l'équation différentielle","calculer la période","étudier l'énergie"],"parties":[{"t":"L'équation","html":"<div class='def'><b>Résultat</b>Pour un pendule élastique horizontal sans frottement : <strong>x'' + (k/m) x = 0</strong>.</div>"},{"t":"La période","verrou":true},{"t":"Énergie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":16,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un technicien de Douala étudie la suspension d'un taxi, modélisée par un ressort.","tache":"Explique ce qui arrive à la période si le taxi est plus chargé."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r17",{"duree":25,"titre":"Le pendule en rotation","accroche":"Le balancier de torsion oscille autour d'un fil.","intro":"Un solide oscillant autour d'un axe obéit à une équation analogue à celle d'un ressort.","objectifs":["établir l'équation de rotation","calculer la période","comparer aux oscillateurs de translation"],"parties":[{"t":"L'équation","html":"<div class='def'><b>Résultat</b>Pour un pendule de torsion : <strong>θ'' + (C/J) θ = 0</strong>, où C est la constante de torsion et J le moment d'inertie.</div>"},{"t":"Période","verrou":true},{"t":"Pendule pesant","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":17,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un artisan horloger de Douala répare le balancier d'une ancienne horloge à torsion.","tache":"Dis ce qui modifie la période."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r20",{"duree":20,"titre":"Condensateur plan et associations","accroche":"Plus les plaques sont proches, plus la capacité est grande.","intro":"La capacité dépend de la géométrie, et les associations de condensateurs modifient la capacité globale.","objectifs":["calculer C d'un condensateur plan","associer des condensateurs","calculer l'énergie"],"parties":[{"t":"Condensateur plan","html":"<div class='def'><b>Formule</b>La capacité d'un <strong>condensateur plan</strong> est <strong>C = ε S / d</strong>.</div>"},{"t":"Associations","verrou":true},{"t":"Énergie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":20,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un réparateur de Bafang ne dispose que de condensateurs de 10 µF et veut obtenir 20 µF.","tache":"Indique l'association à réaliser."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r21",{"duree":25,"titre":"Circuits RC, RL et LC","accroche":"Trois circuits, trois comportements.","intro":"L'établissement du courant et la décharge se décrivent par des équations différentielles.","objectifs":["donner les constantes de temps","décrire les circuits","calculer la période propre"],"parties":[{"t":"RC et RL","html":"<div class='def'><b>Constantes de temps</b>Circuit RC : <strong>τ = RC</strong>. Circuit RL : <strong>τ = L/R</strong>.</div>"},{"t":"Circuit LC","verrou":true},{"t":"Énergie","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":21,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un technicien radio de Bafoussam veut accorder un circuit à une fréquence précise.","tache":"Quelle relation lui sert ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r22",{"duree":25,"titre":"Oscillations libres et forcées du circuit RLC","accroche":"La résistance amortit, l'excitateur entretient.","intro":"Le circuit RLC se comporte comme un oscillateur mécanique amorti.","objectifs":["décrire les oscillations libres","décrire les oscillations forcées","définir les régimes"],"parties":[{"t":"Oscillations libres","html":"<div class='def'><b>Définitions</b>Des <strong>oscillations libres</strong> se produisent sans générateur après la charge du condensateur. Des <strong>oscillations forcées</strong> sont imposées par un générateur.</div>"},{"t":"Régimes","verrou":true},{"t":"Équation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":22,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Dans un poste de radio réparé à Mbouda, un signal oscille puis s'éteint progressivement.","tache":"Identifie le régime."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r23",{"duree":25,"titre":"Réponse en intensité et puissance du RLC","accroche":"À la résonance, le courant est maximal.","intro":"La résonance d'intensité permet de sélectionner une fréquence, comme dans un récepteur radio.","objectifs":["décrire la résonance","calculer la fréquence propre","calculer la puissance"],"parties":[{"t":"La résonance","html":"<div class='def'><b>Résultat</b>La <strong>résonance d'intensité</strong> a lieu pour <strong>L C ω² = 1</strong>. Alors Z = R, et l'intensité est maximale.</div>"},{"t":"Puissance","verrou":true},{"t":"Exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":23,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Le récepteur d'une radio communautaire de Garoua doit capter une seule station.","tache":"Explique le rôle du circuit RLC."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r24",{"duree":20,"titre":"Les dipôles commandés et les capteurs","accroche":"Une résistance qui varie avec la lumière.","intro":"Certains composants traduisent une grandeur physique en grandeur électrique.","objectifs":["définir un dipôle commandé","citer des capteurs","expliquer le principe"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>dipôle commandé</strong> a une caractéristique qui dépend d'une grandeur extérieure : lumière, température ou tension de commande.</div>"},{"t":"Exemples","verrou":true},{"t":"Capter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":24,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un projet de lampadaire solaire de quartier à Bafia doit s'allumer à la tombée de la nuit.","tache":"Propose un capteur."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r25",{"duree":20,"titre":"Les chaînes électroniques","accroche":"Du capteur à l'action.","intro":"Une chaîne électronique transforme un signal pour commander une action.","objectifs":["identifier les étages","schématiser une chaîne","donner des exemples"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>chaîne électronique</strong> est un ensemble d'étages : acquisition, traitement, amplification et sortie.</div>"},{"t":"Exemples","verrou":true},{"t":"Schéma","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":25,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un groupe d'élèves de Bafoussam conçoit une alarme contre les vols de poules.","tache":"Présente la chaîne électronique."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r30",{"duree":20,"titre":"L'effet Doppler","accroche":"La sirène monte, puis descend.","intro":"La fréquence perçue dépend du mouvement de la source ou du récepteur.","objectifs":["décrire l'effet","calculer une fréquence","citer des applications"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet Doppler</strong> est le changement de fréquence perçue lorsque la source et le récepteur sont en mouvement relatif.</div>"},{"t":"Formule","verrou":true},{"t":"Applications","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":30,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Une ambulance passe près du lycée de Bonamoussadi à Douala. Le son paraît changer.","tache":"Explique ce changement."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r32",{"duree":20,"titre":"L'effet Compton","accroche":"Un photon perd de l'énergie comme une bille qui en heurte une autre.","intro":"L'effet Compton confirme que la lumière a aussi un comportement corpusculaire.","objectifs":["définir l'effet Compton","utiliser la relation","interpréter"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>effet Compton</strong> est la diffusion d'un photon par un électron peu lié, avec augmentation de la longueur d'onde du photon.</div>"},{"t":"La relation","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":32,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"En radiologie, à l'hôpital Laquintinie, des rayons X de longueur d'onde 71,0 pm diffusés à 90° par la matière ressortent avec une longueur d'onde de 73,4 pm.","tache":"Identifie l'effet et vérifie la valeur mesurée (h/(mₑc) = 2,43 pm)."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-physique-r33",{"duree":25,"titre":"Spectre de l'atome d'hydrogène","accroche":"Quatre raies visibles révèlent les niveaux d'énergie.","intro":"L'énergie de l'atome d'hydrogène ne prend que certaines valeurs.","objectifs":["utiliser En","calculer l'énergie d'une transition","calculer une longueur d'onde"],"parties":[{"t":"Les niveaux","html":"<div class='def'><b>Résultat</b>L'énergie de l'atome d'hydrogène est quantifiée : <strong>E_n = −13,6 / n²</strong> (en eV).</div>"},{"t":"Transitions","verrou":true},{"t":"Séries","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"physique","rang":33,"apc":{"module":"Physique de Terminale","famille":"Compréhension et usage des phénomènes physiques dans la vie courante","agir":"Modéliser, mesurer et argumenter","situation":"Un club d'astronomie de Dschang observe la raie rouge de l'hydrogène dans une nébuleuse.","tache":"Calcule la longueur d'onde de la transition de n = 3 à n = 2."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r01",{"duree":20,"titre":"La cellule en microscopie optique","accroche":"Une cellule se prépare avant de se regarder.","intro":"La cellule est l'unité de base du vivant. Le microscope optique en montre l'organisation générale.","objectifs":["décrire une cellule animale et végétale","préparer une lame","calculer une taille réelle"],"parties":[{"t":"L'organisation de la cellule","html":"<div class='def'><b>Définition</b>La <strong>cellule</strong> est l'unité structurale et fonctionnelle des êtres vivants. Elle comprend une membrane, un cytoplasme et un noyau.</div>"},{"t":"Animale et végétale","html":"<p>La cellule végétale possède en plus une paroi cellulosique, des vacuoles développées et des chloroplastes.</p>","retenir":"Paroi : cellule végétale seulement.","labo":{"type":"osmose","c":9,"veg":true}},{"t":"Observer","html":"<p class='formule'>Taille réelle = taille mesurée / grossissement</p>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> La cellule animale se distingue de la cellule végétale car elle possède :</p><ol type='a'><li>des chloroplastes</li><li>des centrosomes</li><li>une paroi pectocellulosique</li><li>une grande vacuole</li></ol><details><summary>Voir la réponse</summary><p><strong>des centrosomes</strong>. Les centrioles du centrosome sont absents chez la plupart des végétaux supérieurs.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Image de 10 mm au grossissement × 500 : taille réelle ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 20 µm.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Limiter les conséquences d'un mauvais fonctionnement cellulaire.</p><p><strong>Situation.</strong> Ta petite sœur a observé au microscope, au grossissement × 400, des cellules d'épiderme d'oignon et des cellules de sa joue. Elle a dessiné une cellule de 2 cm et affirme que « toutes les cellules sont pareilles ».</p><p><strong>Consigne 1.</strong> Calcule la taille réelle de la cellule dessinée.</p><p><strong>Consigne 2.</strong> Dans un texte d'une dizaine de lignes, montre-lui les points communs et les différences entre cellule végétale et cellule animale.</p><details><summary>Voir une réponse attendue</summary><p>2 cm/400 = 0,005 cm = 50 µm. Points communs : membrane plasmique, cytoplasme, noyau. La cellule végétale possède en plus une paroi pectocellulosique, une grande vacuole et des chloroplastes (dans les parties vertes) ; la cellule animale n'a ni paroi ni chloroplaste et ses vacuoles sont petites. Les cellules ne sont donc pas toutes pareilles.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Membrane, cytoplasme, noyau.","Paroi et chloroplastes chez le végétal."],"exo":"<p>Image de 10 mm au grossissement × 500 : taille réelle ? <em>(Réponse : 20 µm.)</em></p>","quiz":[{"q":"La cellule animale se distingue de la cellule végétale car elle possède :","r":["des chloroplastes","des centrosomes","une paroi pectocellulosique","une grande vacuole"],"b":1,"e":"Les centrioles du centrosome sont absents chez la plupart des végétaux supérieurs."},{"q":"Au microscope optique, on distingue dans une cellule :","r":["les ribosomes et le réticulum endoplasmique","les crêtes mitochondriales","le noyau, le cytoplasme et la membrane","les pores nucléaires"],"b":2,"e":"Les autres structures nécessitent le microscope électronique."},{"q":"Le grossissement d'un microscope muni d'un objectif ×40 et d'un oculaire ×10 est :","r":["×50","×4 000","×30","×400"],"b":3,"e":"On multiplie les deux grossissements."},{"q":"Le vert de méthyle acétique colore :","r":["le noyau","la paroi","l'amidon","les lipides"],"b":0,"e":"Il se fixe sur l'ADN."},{"q":"La paroi des cellules végétales est formée surtout de :","r":["protéines et lipides membranaires","cellulose et pectine","amidon et glycogène","chitine et kératine"],"b":1,"e":"Elle est rigide et perméable."},{"q":"La cellule est l'unité :","r":["de mesure des longueurs microscopiques","de la matière minérale des roches","structurale et fonctionnelle du vivant","de classification des espèces"],"b":2,"e":"Tout être vivant est formé de cellules."},{"q":"Une cellule d'épiderme d'oignon ne contient pas :","r":["de noyau entouré d'une enveloppe","de vacuole remplie de suc","de paroi pectocellulosique","de chloroplastes"],"b":3,"e":"Le bulbe d'oignon pousse à l'abri de la lumière."},{"q":"Le cytoplasme contient :","r":["les organites baignant dans le hyaloplasme","uniquement de l'eau et des sels minéraux","le noyau seulement, sans organite","la paroi et la membrane plasmique"],"b":0,"e":"C'est le milieu situé entre membrane et noyau."},{"q":"Un dessin d'observation doit comporter :","r":["des couleurs vives et des ombres pour le relief","un titre, des légendes et le grossissement","seulement le nom de l'élève et la date","un dessin sans légende mais très précis"],"b":1,"e":"Ce sont les règles du dessin scientifique."},{"q":"La membrane plasmique est :","r":["une paroi rigide de cellulose et de pectine","une double couche d'ADN et de protéines","une bicouche de phospholipides avec des protéines","une couche imperméable à toutes les substances"],"b":2,"e":"C'est le modèle de la mosaïque fluide."}],"c":"Tle C","m":"svt","rang":1,"apc":{"module":"La cellule et ses échanges","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Au lycée de Bafia, un élève compare une cellule d'oignon et une cellule de sa joue au microscope.","tache":"Présente deux différences observables."},"gratuit":true});
VRT_L("tle-c-svt-r02",{"duree":20,"titre":"Osmose et dialyse : interpréter les échanges d'eau","accroche":"Une feuille d'oignon plasmolysée dans l'eau salée.","intro":"L'eau traverse la membrane selon la concentration des milieux. C'est un phénomène demandé chaque année.","objectifs":["définir osmose et dialyse","prévoir le sens de l'eau","interpréter turgescence et plasmolyse"],"parties":[{"t":"Osmose et dialyse","html":"<div class='def'><b>Définition</b>L'<strong>osmose</strong> est le passage de l'eau à travers une membrane, du milieu le moins concentré vers le milieu le plus concentré. La <strong>dialyse</strong> est le passage de petites molécules de solutés.</div>"},{"t":"Les trois milieux","verrou":true},{"t":"Le cas des globules rouges","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":2,"apc":{"module":"La cellule et ses échanges","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Ton camarade s'étonne que des cellules animales vivant en eau de mer gardent leur aspect normal, alors qu'une cellule en milieu hypertonique se crénelle.","tache":"Explique ce qui leur permet de limiter la perte d'eau."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r03",{"duree":20,"titre":"Échanges de substances dissoutes","accroche":"Une cellule peut accumuler une substance contre son gradient.","intro":"La membrane contrôle ce qui entre et sort. Le transport peut être passif ou actif.","objectifs":["distinguer transports passif et actif","citer les protéines de transport","expliquer la pompe Na⁺/K⁺"],"parties":[{"t":"Le transport passif","html":"<div class='def'><b>Définition</b>Le <strong>transport passif</strong> s'effectue dans le sens du gradient de concentration, sans dépense d'énergie : diffusion simple ou facilitée.</div>"},{"t":"Le transport actif","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":3,"apc":{"module":"La cellule et ses échanges","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Pendant une diarrhée, un infirmier de Maroua conseille à une mère une solution de réhydratation contenant sel et sucre.","tache":"Explique le lien avec les transports intestinaux."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r04",{"duree":20,"titre":"Endocytose et exocytose","accroche":"La cellule peut avaler ou rejeter de grosses particules.","intro":"Certaines particules trop grosses franchissent la membrane grâce à des vésicules.","objectifs":["définir endocytose et exocytose","donner des exemples","expliquer leur importance"],"parties":[{"t":"Les deux mécanismes","html":"<div class='def'><b>Définition</b>L'<strong>endocytose</strong> fait entrer des particules par invagination de la membrane. L'<strong>exocytose</strong> rejette des substances par fusion de vésicules avec la membrane.</div>"},{"t":"Exemples","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":4,"apc":{"module":"La cellule et ses échanges","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Une biologiste de Yaoundé observe au microscope un macrophage qui émet des prolongements autour d'une bactérie ; 2 minutes plus tard, la bactérie est dans une vésicule à l'intérieur de la cellule, et 20 minutes après, elle a disparu.","tache":"Identifie le mécanisme et décris ses étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r05",{"duree":20,"titre":"Intégration : les échanges cellulaires","accroche":"Sérum physiologique ou eau pure ?","intro":"Une erreur de perfusion peut être très dangereuse. Cette situation mobilise les échanges cellulaires.","objectifs":["mobiliser les échanges","argumenter","rédiger une réponse"],"parties":[{"t":"Compétence","html":"<div class='def'><b>Définition</b>Une <strong>solution isotonique</strong> au sang ne provoque pas de flux net d'eau pour les globules rouges.</div>"},{"t":"Analyse","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":5,"apc":{"module":"La cellule et ses échanges","famille":"Recherche d'un meilleur équilibre de vie","agir":"Limiter les conséquences d'un mauvais fonctionnement cellulaire","situation":"Un aide-soignant de Bertoua veut remplacer une perfusion de sérum physiologique par de l'eau distillée.","tache":"Explique le danger."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r08",{"duree":20,"titre":"La méiose","accroche":"Deux divisions pour passer de 2n à n.","intro":"La méiose produit des cellules haploïdes et brasse l'information génétique.","objectifs":["décrire les deux divisions","expliquer le passage de 2n à n","expliquer les brassages"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>méiose</strong> est une suite de deux divisions qui donne, à partir d'une cellule diploïde (2n), quatre cellules haploïdes (n).</div>"},{"t":"Les divisions","verrou":true},{"t":"Les brassages","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":8,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Un élève de Dschang se demande pourquoi deux frères n'ont pas le même patrimoine génétique.","tache":"Explique le rôle de la méiose."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r10",{"duree":20,"titre":"La fécondation chez les mammifères","accroche":"Une rencontre qui rétablit 2n.","intro":"La fécondation unit deux gamètes et compense la méiose.","objectifs":["décrire les étapes","expliquer le rétablissement de 2n","préciser son importance"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>fécondation</strong> est l'union d'un gamète mâle et d'un gamète femelle, formant une cellule-œuf diploïde.</div>"},{"t":"Les étapes","verrou":true},{"t":"Importance","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":10,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Au centre de procréation médicalement assistée de Yaoundé, un biologiste photographie un ovule fécondé in vitro : 1 h, ovocyte entouré de spermatozoïdes ; 6 h, deux pronucléi éloignés ; 12 h, pronucléi accolés ; 24 h, embryon à deux cellules.","tache":"Classe et explique ces étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r09",{"duree":20,"titre":"Intégration : reproduction et continuité de l'espèce","accroche":"Méiose et fécondation se complètent.","intro":"L'alternance méiose-fécondation maintient le nombre de chromosomes de l'espèce.","objectifs":["relier méiose et fécondation","exploiter un document","argumenter"],"parties":[{"t":"Rappel","html":"<div class='def'><b>Définition</b>La <strong>méiose</strong> divise le nombre de chromosomes par deux ; la <strong>fécondation</strong> le rétablit.</div>"},{"t":"Exploiter un document","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":9,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Dans un exposé à Limbé, un élève affirme que les enfants ont 92 chromosomes, puisqu'ils reçoivent les 46 de leur père et les 46 de leur mère.","tache":"Corrige-le en expliquant le rôle de la méiose et de la fécondation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r11",{"duree":20,"titre":"Intégration : reproduction et continuité de l'espèce","accroche":"Méiose et fécondation se complètent.","intro":"L'alternance méiose-fécondation maintient le nombre de chromosomes de l'espèce.","objectifs":["relier méiose et fécondation","exploiter un document","argumenter"],"parties":[{"t":"Rappel","html":"<div class='def'><b>Définition</b>La <strong>méiose</strong> divise le nombre de chromosomes par deux ; la <strong>fécondation</strong> le rétablit.</div>"},{"t":"Exploiter un document","verrou":true},{"t":"Rédaction","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":11,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Dans un exposé à Limbé, un élève affirme que les enfants ont 92 chromosomes, puisqu'ils reçoivent les 46 de leur père et les 46 de leur mère.","tache":"Corrige-le en expliquant le rôle de la méiose et de la fécondation."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r12",{"duree":20,"titre":"Monohybridisme avec dominance","accroche":"Les lois de Mendel à partir d'un seul caractère.","intro":"Un croisement entre lignées pures permet de déduire le mode de transmission d'un caractère.","objectifs":["définir les termes","établir un échiquier","analyser un test-cross"],"parties":[{"t":"Vocabulaire","html":"<div class='def'><b>Définition</b>Le <strong>monohybridisme</strong> étudie la transmission d'un seul caractère. Un allèle <strong>dominant</strong> s'exprime chez l'hétérozygote, l'allèle <strong>récessif</strong> y est masqué.</div>"},{"t":"Résultats","verrou":true},{"t":"Test-cross","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":12,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Un éleveur de porcs de Bafia remarque des naissances à longue et courte queue dans une même portée.","tache":"Propose une démarche pour comprendre ce résultat."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r13",{"duree":20,"titre":"Le dihybridisme","accroche":"Deux caractères, seize cases.","intro":"Le dihybridisme étudie la transmission simultanée de deux caractères.","objectifs":["établir un échiquier","reconnaître 9-3-3-1","interpréter un test-cross"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>dihybridisme</strong> étudie la transmission de deux caractères. Pour des gènes indépendants, on obtient en F₂ les proportions <strong>9/16 - 3/16 - 3/16 - 1/16</strong>.</div>"},{"t":"Test-cross","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":13,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Un agronome de l'Ouest croise deux variétés de maïs différant par deux caractères.","tache":"Dis quels résultats attendre en F₂ si les gènes sont indépendants."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r14",{"duree":20,"titre":"Le brassage intrachromosomique","accroche":"Des gènes liés peuvent se séparer.","intro":"Si les gènes sont portés par le même chromosome, les proportions diffèrent.","objectifs":["reconnaître des gènes liés","calculer un pourcentage de recombinaison","expliquer le crossing-over"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Des <strong>gènes liés</strong> sont portés par le même chromosome. Le <strong>crossing-over</strong> produit des gamètes recombinés.</div>"},{"t":"Test-cross","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":14,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Dans une expérience de génétique, un test-cross donne deux phénotypes parentaux à 45 % chacun et deux recombinés à 5 % chacun.","tache":"Conclus."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r15",{"duree":20,"titre":"Transmissions autosomiques","accroche":"Albinisme, drépanocytose, achondroplasie.","intro":"Certaines maladies se transmettent par des gènes portés par des autosomes.","objectifs":["reconnaître le mode de transmission","écrire les génotypes","calculer un risque"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une transmission <strong>autosomique</strong> concerne un gène porté par un chromosome non sexuel. Elle est récessive ou dominante.</div>"},{"t":"Exemples","verrou":true},{"t":"Risque","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":15,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Dans une campagne à Douala sur la drépanocytose (allèle S récessif), on présente quatre couples : AA × AS ; AS × AS ; AS × SS ; AA × SS.","tache":"Calcule pour chaque couple le risque d'enfant SS et dis quelles unions présenter comme à risque."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r16",{"duree":20,"titre":"Transmissions gonosomiques","accroche":"Daltonisme et hémophilie touchent surtout les garçons.","intro":"Une maladie portée par X s'exprime plus souvent chez l'homme.","objectifs":["reconnaître une transmission liée à X","calculer un risque","expliquer le rôle de la mère"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une transmission <strong>gonosomique récessive</strong> liée à X touche davantage les hommes, qui ne possèdent qu'un chromosome X.</div>"},{"t":"Exemples","verrou":true},{"t":"Risque","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":16,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Une famille de Yaoundé a plusieurs garçons hémophiles et aucune fille atteinte.","tache":"Explique cette répartition."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r17",{"duree":20,"titre":"Intégration : limiter les maladies génétiques","accroche":"Causerie, échiquier, affiche et slogan.","intro":"Le bac demande de passer de la connaissance à l'action de sensibilisation.","objectifs":["préparer une causerie","présenter des échiquiers","rédiger un slogan"],"parties":[{"t":"Compétence","html":"<div class='def'><b>Définition</b><strong>Limiter la fréquence d'une maladie génétique</strong>, c'est informer, dépister et conseiller les familles.</div>"},{"t":"La causerie","verrou":true},{"t":"Affiche et slogan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":17,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Le couple X a cinq enfants drépanocytaires, alors que les parents se disent en bonne santé. Un médecin te sollicite pour une campagne.","tache":"Présente un texte de causerie et un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r06",{"duree":20,"titre":"Acides nucléiques et duplication de l'ADN","accroche":"Deux mètres d'ADN recopiés dans chaque cellule.","intro":"L'ADN porte l'information génétique. Sa structure explique sa copie fidèle avant chaque division.","objectifs":["décrire l'ADN et l'ARN","appliquer la complémentarité des bases","expliquer la réplication semi-conservative"],"parties":[{"t":"La structure de l'ADN","html":"<div class='def'><b>Définition</b>L'<strong>ADN</strong> est une double hélice de nucléotides. Chaque nucléotide comprend un phosphate, un désoxyribose et une base : A, T, C ou G.</div>"},{"t":"Complémentarité et ARN","verrou":true},{"t":"La réplication","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":6,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Pour un TP au lycée de Mutengene, les élèves construisent une maquette d'ADN avec des pailles et des capsules colorées.","tache":"Indique les règles à respecter."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r07",{"duree":20,"titre":"Biosynthèse des protéines","accroche":"Du gène au caractère.","intro":"Un gène commande la fabrication d'une protéine qui détermine un caractère.","objectifs":["décrire transcription et traduction","utiliser le code génétique","relier protéine et caractère"],"parties":[{"t":"Du gène à la protéine","html":"<div class='def'><b>Définition</b>La <strong>transcription</strong> copie un gène en ARN messager dans le noyau. La <strong>traduction</strong> assemble les acides aminés au niveau des ribosomes.</div>"},{"t":"Le code génétique","verrou":true},{"t":"Protéine et caractère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":7,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Lors d'une visite à l'hôpital Laquintinie, un médecin montre l'hémoglobine S d'un malade drépanocytaire.","tache":"Explique le lien entre gène et maladie."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r18",{"duree":20,"titre":"Structure du tissu nerveux","accroche":"Des milliards de cellules connectées.","intro":"Le tissu nerveux réunit les neurones et leurs cellules de soutien.","objectifs":["décrire un neurone","distinguer substance grise et blanche","préparer une dissection"],"parties":[{"t":"Le neurone","html":"<div class='def'><b>Définition</b>Le <strong>neurone</strong> est la cellule nerveuse. Il comprend un corps cellulaire, des dendrites et un axone.</div>"},{"t":"Substances grise et blanche","verrou":true},{"t":"Le nerf","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":18,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"En TP à Bamenda, un groupe prépare la dissection de l'encéphale d'un petit mammifère.","tache":"Cite trois règles à respecter."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r19",{"duree":20,"titre":"Le potentiel d'action","accroche":"Tout ou rien : le neurone ne chuchote pas.","intro":"Une stimulation suffisante provoque une inversion brève du potentiel de membrane.","objectifs":["décrire le potentiel d'action","expliquer les mouvements d'ions","appliquer la loi du tout ou rien"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>potentiel d'action</strong> est une inversion brève et propagée de la polarité membranaire, déclenchée à partir d'un seuil.</div>"},{"t":"Les phases","verrou":true},{"t":"Propriétés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":19,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Un élève de Mbalmayo augmente l'intensité d'un stimulus et croit que chaque potentiel d'action devient plus grand.","tache":"Corrige son idée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r20",{"duree":20,"titre":"Propagation du potentiel d'action","accroche":"Jusqu'à plus de 100 m/s sur certaines fibres.","intro":"Le potentiel d'action se propage de proche en proche ou de nœud en nœud.","objectifs":["comparer les conductions","calculer une vitesse","expliquer le rôle de la myéline"],"parties":[{"t":"Les modes de conduction","html":"<div class='def'><b>Définition</b>Dans une fibre sans myéline, la conduction est <strong>de proche en proche</strong>. Dans une fibre myélinisée, elle est <strong>saltatoire</strong>, d'un nœud de Ranvier à l'autre.</div>"},{"t":"La vitesse","verrou":true},{"t":"La période réfractaire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":20,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Un enregistrement à deux électrodes sépare de 4 cm un même potentiel d'action, avec un retard de 1 ms.","tache":"Calcule la vitesse."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r21",{"duree":20,"titre":"La synapse : fonctionnement","accroche":"Un message électrique devient chimique, puis redevient électrique.","intro":"La transmission synaptique met en jeu un neurotransmetteur.","objectifs":["décrire les étapes","expliquer le rôle du Ca²⁺","distinguer PPSE et PPSI"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La <strong>transmission synaptique</strong> : l'arrivée du potentiel d'action provoque l'entrée de Ca²⁺, l'exocytose du neurotransmetteur et sa fixation sur des récepteurs postsynaptiques.</div>"},{"t":"PPSE et PPSI","verrou":true},{"t":"Fin du message","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":21,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"On stimule un neurone présynaptique et on enregistre : potentiel d'action présynaptique à t = 0 ; dépolarisation de la cellule postsynaptique à t = 0,5 ms. Sur une même fibre sans synapse, le message parcourt la même distance en 0,01 ms.","tache":"Explique ce délai."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r22",{"duree":20,"titre":"Intégration : drogues et message nerveux","accroche":"Un camarade propose un comprimé avant l'examen.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Une <strong>substance psychoactive</strong> modifie la transmission synaptique.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":22,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Avant les examens à Bafia, un camarade propose un comprimé censé empêcher de dormir.","tache":"Rédige un conseil argumenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r23",{"duree":20,"titre":"Origine des cellules immunitaires et reconnaissance du non-soi","accroche":"Tout commence dans la moelle osseuse.","intro":"Les cellules immunitaires naissent dans la moelle osseuse et se répartissent dans l'organisme.","objectifs":["citer les cellules","préciser leur origine","réaliser un frottis"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>leucocytes</strong> proviennent de cellules souches de la moelle osseuse.</div>"},{"t":"Maturation","html":"<p>Les lymphocytes B mûrissent dans la moelle osseuse, les lymphocytes T dans le thymus.</p>","retenir":"LT : thymus.","labo":{"type":"trier","invite":"Choisis une cellule.","items":[["Macrophage","phagocytose."],["Lymphocyte B","donne des plasmocytes."],["Lymphocyte T4","coordonne."],["Lymphocyte T8","détruit les cellules infectées."]]}},{"t":"Le soi et l'antigène","html":"<p>Le <strong>soi</strong> regroupe les molécules propres à l'individu. Un <strong>antigène</strong> est reconnu comme étranger. L'anticorps, en forme de Y, s'y fixe spécifiquement.</p>","retenir":"Un anticorps, un antigène."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Les lymphocytes naissent dans :</p><ol type='a'><li>le cœur</li><li>la moelle osseuse</li><li>le foie adulte</li><li>la peau</li></ol><details><summary>Voir la réponse</summary><p><strong>la moelle osseuse</strong>. Ils dérivent de cellules souches hématopoïétiques.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Où mûrissent les lymphocytes T ?</p><details><summary>Voir la réponse</summary><p>(Réponse : dans le thymus.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Comprendre et préserver les défenses de l'organisme.</p><p><strong>Situation.</strong> Le frottis sanguin d'un patient montre de nombreux granulocytes, quelques monocytes et des lymphocytes. Le laborantin explique que toutes ces cellules viennent du même endroit.</p><p><strong>Consigne 1.</strong> Indique l'organe où naissent les cellules immunitaires et ceux où mûrissent les lymphocytes B et T.</p><p><strong>Consigne 2.</strong> Explique comment l'organisme reconnaît le soi et le non-soi.</p><details><summary>Voir une réponse attendue</summary><p>Elles naissent dans la moelle osseuse rouge à partir de cellules souches ; les lymphocytes B y mûrissent, les lymphocytes T mûrissent dans le thymus. Le soi est défini par les marqueurs du CMH (HLA) présents sur les cellules ; les lymphocytes reconnaissent, grâce à leurs récepteurs, les antigènes étrangers (non-soi) ou un soi modifié.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Moelle osseuse.","Thymus.","Organes lymphoïdes."],"exo":"<p>Où mûrissent les lymphocytes T ? <em>(Réponse : dans le thymus.)</em></p>","quiz":[{"q":"Les lymphocytes naissent dans :","r":["le cœur","la moelle osseuse","le foie adulte","la peau"],"b":1,"e":"Ils dérivent de cellules souches hématopoïétiques."},{"q":"Les lymphocytes T mûrissent dans :","r":["la moelle","la rate","le thymus","l'intestin"],"b":2,"e":"T vient de thymus."},{"q":"Les lymphocytes B mûrissent dans :","r":["le thymus","les ganglions","le cerveau","la moelle osseuse"],"b":3,"e":"Ils y acquièrent leurs récepteurs."},{"q":"Le soi est caractérisé par :","r":["les molécules du CMH","les anticorps circulants","les microbes de la flore intestinale","le volume de sang"],"b":0,"e":"Elles sont propres à chaque individu."},{"q":"Les LT reconnaissent un antigène :","r":["libre dans le plasma, sans présentation","associé à une molécule du CMH","sans récepteur membranaire","dans le noyau de la cellule infectée"],"b":1,"e":"C'est la double reconnaissance."},{"q":"Les LB reconnaissent l'antigène :","r":["par les molécules du CMH","par phagocytose de l'antigène","par leurs anticorps membranaires","par des hormones sécrétées"],"b":2,"e":"Ils le reconnaissent sous forme native."},{"q":"Les organes lymphoïdes secondaires sont :","r":["la moelle et le thymus","le cœur et les reins","les os","les ganglions et la rate"],"b":3,"e":"C'est le lieu des réponses immunitaires."},{"q":"La cellule présentatrice de l'antigène est par exemple :","r":["un macrophage ou une cellule dendritique","un globule rouge qui transporte l'antigène","une plaquette fixée sur le microbe","un plasmocyte qui sécrète des anticorps"],"b":0,"e":"Elle présente des fragments d'antigène aux LT4."},{"q":"La sélection des lymphocytes non autoréactifs assure :","r":["la mémoire immunitaire","la tolérance du soi","la phagocytose","la vaccination"],"b":1,"e":"Les lymphocytes dangereux sont éliminés."},{"q":"Le non-soi modifié correspond par exemple à :","r":["un globule rouge sain de l'individu","un neurone sain","une cellule infectée par un virus","une hormone de l'organisme"],"b":2,"e":"Elle présente des peptides viraux."}],"c":"Tle C","m":"svt","rang":23,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Un laborantin de Limbé réalise un frottis sanguin pour un examen de routine.","tache":"Dis ce qu'il observera."},"gratuit":true});
VRT_L("tle-c-svt-r24",{"duree":20,"titre":"Réponse non spécifique et réponse à médiation cellulaire","accroche":"La première ligne de défense.","intro":"Elle agit rapidement contre une grande variété d'agents infectieux.","objectifs":["citer les barrières","décrire l'inflammation","décrire la phagocytose"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>réponse non spécifique</strong> s'exerce sans reconnaissance préalable d'un antigène particulier.</div>"},{"t":"La phagocytose","verrou":true},{"t":"La réponse à médiation cellulaire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":24,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Une plaie au pied d'un agriculteur à Nkongsamba devient rouge et chaude.","tache":"Explique ces signes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r25",{"duree":20,"titre":"Réponse à médiation humorale et mémoire immunitaire","accroche":"LT, LB, plasmocytes : chacun son rôle.","intro":"La réponse spécifique cible un antigène précis.","objectifs":["décrire les étapes","distinguer les deux réponses","expliquer la coopération"],"parties":[{"t":"La réponse humorale","html":"<div class='def'><b>Définition</b>La <strong>réponse humorale</strong> : les LB activés se transforment en plasmocytes qui sécrètent des anticorps circulants.</div>","retenir":"Plasmocytes : anticorps."},{"t":"La mémoire","verrou":true},{"t":"La vaccination","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":25,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Chez un patient vacciné contre le tétanos, on observe dans un ganglion des lymphocytes B qui grossissent, puis des cellules au cytoplasme rempli de réticulum endoplasmique granuleux ; le taux d'anticorps antitétaniques passe de 0,01 à 1 UI/mL.","tache":"Identifie cette cellule et son rôle."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r26",{"duree":20,"titre":"Maladies auto-immunes","accroche":"Quand le système se trompe de cible.","intro":"Dans certaines maladies, le système immunitaire attaque les constituants de l'organisme.","objectifs":["définir l'auto-immunité","donner des exemples","expliquer le traitement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>maladie auto-immune</strong> résulte d'une réaction immunitaire dirigée contre le soi.</div>"},{"t":"Exemples","verrou":true},{"t":"Prise en charge","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":26,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Une jeune fille diabétique à Yaoundé apprend que sa maladie est auto-immune.","tache":"Explique ce terme."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r27",{"duree":20,"titre":"Pandémies et VIH/sida","accroche":"Un virus qui s'attaque aux défenseurs.","intro":"Une pandémie a des conséquences sanitaires et socioculturelles majeures.","objectifs":["expliquer l'action du VIH","interpréter une sérologie","lutter contre la stigmatisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>pandémie</strong> est une épidémie qui s'étend à de très vastes territoires. Le <strong>VIH</strong> détruit progressivement les lymphocytes T4.</div>"},{"t":"La sérologie","verrou":true},{"t":"Conséquences et prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":27,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Dans un quartier de Douala, des voisins évitent une personne vivant avec le VIH.","tache":"Rédige un message pour lutter contre cette attitude."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r28",{"duree":20,"titre":"Régulation des hormones sexuelles chez l'homme","accroche":"Un thermostat hormonal.","intro":"La sécrétion de testostérone est contrôlée par l'axe hypothalamo-hypophysaire.","objectifs":["citer les rôles de la testostérone","décrire le contrôle","expliquer le rétrocontrôle"],"parties":[{"t":"La testostérone","html":"<div class='def'><b>Définition</b>La <strong>testostérone</strong> est l'hormone sexuelle mâle, sécrétée par les cellules de Leydig. Elle assure les caractères sexuels et participe à la spermatogenèse.</div>"},{"t":"Le contrôle","verrou":true},{"t":"Le rétrocontrôle","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":28,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Après une ablation expérimentale de l'hypophyse chez un rat, le taux de testostérone chute.","tache":"Explique ce résultat."},"verrou":true,"nq":10,"labo":true});
