VRT_L("tle-c-svt-r38",{"duree":20,"titre":"Transformer et conserver la mangue","accroche":"Mangue en saison, jus et séchage toute l'année.","intro":"La transformation réduit les pertes après récolte et crée de la valeur.","objectifs":["décrire les étapes","respecter l'hygiène","calculer un coût simple"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>conservation</strong> consiste à ralentir l'altération des aliments par le séchage, la chaleur ou le sucre.</div>"},{"t":"Les étapes","verrou":true},{"t":"L'hygiène","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":38,"apc":{"module":"Catastrophes et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Une coopérative de femmes à Foumbot perd chaque année une partie de sa récolte.","tache":"Propose une transformation."},"verrou":true,"nq":10,"labo":true});
